INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0570', 'spa', 'Ayer, anoche; por extension, el pasado reciente.', 'Adverbio temporal que significa ''ayer'' o mas especificamente ''anoche,'' reflejando una conexion etimologica con la tarde. En Genesis, las hijas de Lot mencionan ''anoche'' (19:34), y Laban confronta a Jacob sobre sucesos de ''ayer'' (31:29, 42). En 2 Reyes 9:26 se amplia para significar ''recientemente.'' La raiz posiblemente se relaciona con la palabra semitica para ''tarde'' (cf. arabe masa'', asirio mushu ''noche''), lo que explica por que a menudo implica la noche anterior en particular. El uso biblico oscila entre el matiz nocturno y el sentido general de ''ayer.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0571', 'spa', 'Firmeza, fidelidad, verdad; lo confiable, fidedigno y real; frecuentemente emparejado con חֶסֶד como atributo pactual de Dios.', 'אֱמֶת es uno de los términos fundacionales de la Biblia hebrea para designar lo real, lo confiable y lo perdurable. Derivado de la raíz אמן (''ser firme, sostener''), porta una solidez que la palabra española ''verdad'' solo capta parcialmente. Cuando se empareja con חֶסֶד en la célebre hendíadis חֶסֶד וֶאֱמֶת (Gn 24:27; Éx 34:6), no denota una verdad proposicional abstracta, sino fidelidad al pacto: la inquebrantable fiabilidad de un Dios que cumple sus promesas. No obstante, אֱמֶת también abarca la exactitud factual (''¿es verdad?'') y caracteriza a personas como ''hombres de verdad'' (Éx 18:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0572', 'spa', 'Costal, saco para grano — bolsa grande para transportar provisiones, exclusiva de la narrativa de José. Aparece únicamente en Génesis 42–44, donde des', 'Costal, saco para grano — bolsa grande para transportar provisiones, exclusiva de la narrativa de José. Aparece únicamente en Génesis 42–44, donde designa los costales en que los hermanos de José llevaban grano desde Egipto, los mismos en los que el mayordomo escondió la plata y la copa de adivinación. La frase recurrente בְּפִי אַמְתַּחַת (''en la boca del costal'', Gn 42:27; 43:12, 21; 44:1-2, 8) impulsa el suspenso narrativo: cada apertura profundiza el terror de los hermanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0575', 'spa', '¿Dónde? ¿Adónde? ¿Hasta cuándo? Adverbio interrogativo de lugar y (con עַד) de tiempo; también usado indefinidamente como ''a cualquier parte''.', '¿Dónde? ¿Adónde? ¿Hasta cuándo? Adverbio interrogativo de lugar y (con עַד) de tiempo; también usado indefinidamente como ''a cualquier parte''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0576a', 'spa', 'yo (pronombre personal arameo de primera persona)', 'Pronombre personal arameo de primera persona «yo», presente en Daniel y Esdras. En estos textos, tanto las autoridades persas como el propio Daniel emplean este pronombre en decretos oficiales y relatos personales. Las secciones arameas de la Escritura preservan el idioma administrativo real del período persa, cuando el arameo servía como lengua franca en todo el imperio. Este sencillo pronombre lleva consigo el peso de la autoridad personal y del decreto real, marcando declaraciones que determinan el destino de pueblos y la restauración de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0576b', 'spa', 'Yo (arameo) — pronombre personal independiente de primera persona singular en el arameo bíblico. Sus 13 apariciones se limitan a las secciones arameas', 'Yo (arameo) — pronombre personal independiente de primera persona singular en el arameo bíblico. Sus 13 apariciones se limitan a las secciones arameas de Daniel y Esdras, donde funciona como pronombre sujeto enfático en discursos reales y visionarios. Nabucodonosor lo emplea repetidamente en sus decretos y relatos de sueños (''Yo, Nabucodonosor'', Dn 4:1, 15, 34), y Daniel lo usa al narrar sus visiones (''Yo, Daniel'', Dn 7:15, 28). También aparece en el decreto de Artajerjes en Esdras 7:21.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0577', 'spa', 'Partícula de súplica: ''por favor, te ruego'', usada al hacer peticiones fervientes o súplicas. Es una interjección de ruego solemne que aparece casi ex', 'Partícula de súplica: ''por favor, te ruego'', usada al hacer peticiones fervientes o súplicas. Es una interjección de ruego solemne que aparece casi exclusivamente en oraciones y súplicas apasionadas. En Génesis 50:17 los hermanos de José imploran perdón; en Éxodo 32:31 Moisés intercede tras el becerro de oro; en 2 Reyes 20:3 Ezequías suplica por su vida; y en Nehemías 1:5, 11 el copero abre su oración a Dios. La palabra señala que el hablante reconoce la gravedad de lo que pide.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0579', 'spa', 'Acontecer, sobrevenir; buscar ocasión o querella contra alguien; de sucesos por designio divino u hostil', 'Verbo poco frecuente que aparece solo cuatro veces, usado para describir eventos que alcanzan a una persona, ya sea por la mano soberana de Dios o por maquinación humana. En Éxodo 21:13 describe a Dios haciendo que un accidente fatal ''acontezca'' a alguien, mientras que en 2 Reyes 5:7 la carta de Naamán se interpreta como ''buscar querella''. Los textos de Salmos y Proverbios (Sal 91:10; Pr 12:21) prometen que ningún mal ''sobrevendrá'' al justo. Las traducciones al español confirman este doble sentido: ''acontecerá'' (suceder) junto a ''buscando ocasión'' (provocar un conflicto).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0581a', 'spa', 'ellos, aquellos (pronombre arameo de tercera persona plural)', 'Pronombre arameo de tercera persona plural «ellos» o «aquellos», usado para identificar grupos o referirse a sujetos mencionados previamente. Daniel y Esdras emplean este pronombre en contextos de decreto real, visión profética e investigación administrativa. Su fuerza demostrativa («aquellos») puede enfatizar una identificación específica: «aquellos reyes», «aquellos hombres». Como otros elementos gramaticales arameos en la Escritura, este pronombre refleja la realidad multilingüe de los períodos exílico y postexílico, cuando el pueblo de Dios vivía bajo imperios de habla aramea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0582', 'spa', 'Hombre, ser humano (individual o genérico); humanidad colectivamente; mortal, ser humano frágil (énfasis poético).', 'Hombre, ser humano (individual o genérico); humanidad colectivamente; mortal, ser humano frágil (énfasis poético).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0583', 'spa', 'Enós, hijo de Set y nieto de Adán; su nacimiento marca el inicio de la invocación del nombre de YHWH.', 'Nombre propio masculino que significa ''hombre'' o ''mortal'' (de la raíz ''-n-sh, que denota fragilidad humana), designando al hijo de Set y nieto de Adán. Enós aparece en las genealogías de Génesis (Gn 4:26; 5:6-11) y en el linaje del Cronista (1 Cr 1:1). Su nacimiento se asocia con una de las notas editoriales más significativas de la Escritura: «Entonces se comenzó a invocar el nombre de YHWH» (Gn 4:26). Las adaptaciones en distintos idiomas reflejan la antigüedad del nombre y sus variantes fonéticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0584', 'spa', 'Gemir o suspirar de angustia; como sustantivo, el que gime o se lamenta. Un verbo que da voz al sufrimiento profundo: el sonido arrancado a quienes pa', 'Gemir o suspirar de angustia; como sustantivo, el que gime o se lamenta. Un verbo que da voz al sufrimiento profundo: el sonido arrancado a quienes padecen aflicción insoportable. Cuando Israel gemía bajo la esclavitud egipcia, esta es la palabra empleada (Éx 2:23). Lamentaciones la usa repetidamente para captar la agonía de Jerusalén tras la destrucción del templo (Lm 1:4, 8). En un caso notable, Ezequiel 9:4 emplea el participio como sustantivo — ''los que gimen'' — para identificar a los justos que lloran, a quienes Dios marca para protección en medio del juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0585', 'spa', 'Suspiro, gemido — el sonido audible del dolor, la angustia o la aflicción espiritual que brota de lo más profundo del sufrimiento. El sustantivo אֲנָח', 'Suspiro, gemido — el sonido audible del dolor, la angustia o la aflicción espiritual que brota de lo más profundo del sufrimiento. El sustantivo אֲנָחָה (anajá) capta la expresión involuntaria y audible de una pena profunda o un dolor físico: el suspiro pesado o gemido que brota de quien está en angustia. Job declara que su suspiro viene en lugar del pan y su gemido se derrama como agua (Job 3:24), convirtiéndolo en sustituto de la vida cotidiana. El salmista se consume de tanto gemir y llorar (Sal 6:6; 31:10; 38:9; 102:5), e Isaías vislumbra un día en que ''el dolor y el gemido huirán'' (Is 35:10; 51:11). Lamentaciones 1:22 lo asocia con un corazón enfermo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0586', 'spa', 'Nosotros (pronombre personal arameo de primera persona del plural, equivalente al hebreo אֲנַחְנוּ)', 'Pronombre personal arameo de primera persona del plural que significa ''nosotros'', presente exclusivamente en las secciones arameas de Esdras y Daniel. Funciona de manera idéntica al hebreo אֲנַחְנוּ, pero refleja las convenciones ortográficas arameas de los documentos bíblicos del período persa. En Daniel 3:16-17, Sadrac, Mesac y Abednego lo usan en su audaz declaración ante Nabucodonosor; en Esdras 4:16 y 5:11, funcionarios judíos lo emplean en correspondencia diplomática. El español lo traduce uniformemente como ''nosotros''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0587', 'spa', 'Nosotros — pronombre independiente de primera persona común plural, usado para énfasis, contraste o como sujeto explícito.', 'אֲנַחְנוּ es el pronombre enfático de primera persona del plural en hebreo bíblico, la contraparte plural de אָנֹכִי/אֲנִי (''yo''). Dado que los verbos hebreos ya codifican su sujeto, el pronombre independiente aparece solo cuando se busca énfasis o contraste: ''todos nosotros somos hijos de un solo hombre'' (Gn 42:11), ''somos hombres honrados'' (Gn 42:31). Frecuentemente sigue a un participio para aportar un sujeto explícito (Gn 19:13; Nm 10:29) o se añade a un verbo finito con fuerza retórica (Jue 9:28; 2 R 10:4). Las formas cognadas a lo largo de la familia semítica — arameo אֲנַחְנָא, árabe نَحْنُ, etíope ንሕና — atestiguan una ascendencia compartida muy profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0589', 'spa', 'אֲנִי — yo; pronombre personal independiente de primera persona del singular en hebreo', 'El pronombre אֲנִי (''yo'') es una de las dos formas hebreas del pronombre personal independiente de primera persona del singular; la otra es אָנֹכִי (H0595). Mientras que אָנֹכִי suele aparecer en contextos más solemnes o arcaicos, אֲנִי es la forma corriente y no marcada, con 874 apariciones en todos los géneros literarios. Figura prominentemente en autodeclaraciones divinas (''Yo soy el SEÑOR tu Dios'', Gn 15:7; Éx 20:2) así como en el habla humana ordinaria. El pronombre no conlleva peso semántico propio más allá de la deixis: señala al hablante. El español yo lo traduce con perfecta consistencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0590', 'spa', 'Nave o flota de naves; sustantivo femenino para embarcaciones, especialmente la flota comercial de Salomón.', 'Sustantivo femenino que designa una nave o, en uso colectivo, una flota de naves. Sus apariciones se concentran en las empresas marítimas de Salomón: la flota construida en Ezión-Guéber sobre el Mar Rojo (1 R 9:26-27), los viajes a Ofir en busca de oro (1 R 10:11) y las «naves de Tarsis» que regresaban cada tres años cargadas de mercancías exóticas (1 R 10:22). La distinción en español entre ''flota'' y ''nave'' refleja la oscilación hebrea entre el sentido colectivo y el singular. Esta palabra evoca vívidamente la breve pero notable era de comercio naval del antiguo Israel bajo la monarquía unida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0591', 'spa', 'Nave, flota, embarcación marítima — un navío grande para el comercio, la guerra o el transporte por mar.', 'Nave, flota, embarcación marítima — un navío grande para el comercio, la guerra o el transporte por mar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0594', 'spa', 'Plomada; instrumento de albañilería para medir la verticalidad, usado figuradamente para el juicio divino', 'Sustantivo que designa una plomada: la cuerda con peso de plomo que el constructor deja caer para verificar si una pared está a plomo. Las cuatro apariciones se concentran en Amós 7:7-8, la célebre visión donde Dios está junto a un muro construido a plomada, sosteniendo una plomada en su mano. La imagen es demoledora: Israel será medido conforme al estándar de Dios y hallado torcido. Los cognados en acadio (anāku) y siríaco apuntan a una conexión con el plomo o estaño, el metal que da peso a la cuerda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0595', 'spa', 'Yo (pronombre enfático de primera persona singular); la forma larga y solemne junto a la más breve אֲנִי.', 'אָנֹכִי es el pronombre enfático de primera persona del singular en hebreo, que coexiste con la forma más breve אֲנִי. Con 359 ocurrencias, aparece de manera prominente en declaraciones solemnes y momentos de alto peso retórico. Dios lo usa para abrir el Decálogo: ''אָנֹכִי YHWH tu Dios'' (Éx 20:2). José se da a conocer con él (Gn 45:3-4). Su cognado acadio anāku y su ausencia del arameo y el árabe sugieren un linaje arcaico. Mientras el hebreo moderno ha abandonado en gran medida אָנֹכִי en favor de אֲנִי, el texto bíblico preserva su registro digno y solemne para la autoidentificación en momentos de gravedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0599', 'spa', 'Airarse o enojarse; verbo denominativo de אַף (nariz/ira), usado casi exclusivamente para referirse a la ira divina. Derivado del sustantivo אַף (''nar', 'Airarse o enojarse; verbo denominativo de אַף (nariz/ira), usado casi exclusivamente para referirse a la ira divina. Derivado del sustantivo אַף (''nariz'', y luego ''ira'', por el resoplar de las fosas nasales), אָנַף expresa el encenderse de la cólera. En la Biblia hebrea se emplea casi exclusivamente para la ira de Dios, lo que lo convierte en un término propio del vocabulario del juicio divino. El Qal describe un estado de enojo (Sal 2:12; 79:5; 85:6; Isa 12:1), mientras que el Hitpael lo intensifica hasta la erupción visible de la furia ante provocaciones específicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0602', 'spa', 'Gemir, clamar de angustia; el gemido profundo e involuntario del herido, del doliente o del oprimido.', 'Verbo que capta el sonido visceral del gemido, ya sea por heridas físicas o por dolor profundo del alma. En Jeremías 51:52 y Ezequiel 26:15, el gemido proviene de los heridos de muerte en batalla (חָלָל). Ezequiel 24:17 prohíbe al profeta gemir como parte de los ritos de duelo, mientras que Ezequiel 9:4 marca para protección divina a quienes gimen y suspiran por las abominaciones de Jerusalén. El español «gemir» y el francés «gémissement» comparten la misma raíz latina (gemere), reflejando la universalidad de este clamor humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0603', 'spa', 'Gemido, clamor; sustantivo que expresa el grito angustiado del oprimido, del pobre o del prisionero.', 'Forma sustantiva del verbo אָנַק (H0602), que denota el clamor sostenido de quienes se hallan en aflicción. Aparece en contextos sálmicos y proféticos profundamente conmovedores: el gemido de los pobres (Sal 12:5), el quejido del prisionero que llega a los oídos de Dios (Sal 79:11; 102:20) y el llanto que acompaña la infidelidad de Israel (Mal 2:13). Cada aparición implica que Dios escucha y responde a tal gemido. Tanto el español «gemido» como el francés «gémissement» derivan del latín gemitus, confirmando la universalidad de este clamor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0605', 'spa', 'Ser débil o enfermar; como adjetivo: incurable, irremediable; como verbo: enfermar gravemente de muerte.', 'De una raíz que significa ''ser débil o enfermo'', esta palabra aparece casi exclusivamente como participio pasivo Qal אָנוּשׁ, funcionando como adjetivo con el sentido de ''incurable'' o ''irremediable''. Los profetas la emplean con devastadora fuerza retórica: Jeremías declara la herida de Judá אָנוּשׁ, incurable (Jer 15:18; 30:12), y Miqueas hace eco para Samaria (Miq 1:9). Quizá el pasaje más memorable es Jeremías 17:9, que la aplica al corazón humano: ''Engañoso es el corazón más que todas las cosas, y perverso (אָנֻשׁ); ¿quién lo conocerá?'' La única aparición verbal en 2 Samuel 12:15, donde el hijo de David ''enfermó gravemente'', conserva la fuerza verbal original de la raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0606', 'spa', 'hombre, humanidad (arameo) — término genérico para un ser humano o la humanidad colectivamente en el arameo bíblico', 'hombre, humanidad (arameo) — término genérico para un ser humano o la humanidad colectivamente en el arameo bíblico');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0607', 'spa', 'Tú (2ms); pronombre arameo de segunda persona masculino singular, equivalente al hebreo attah', 'Tú (2ms); pronombre arameo de segunda persona masculino singular, equivalente al hebreo attah');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0609', 'spa', 'Asa — rey de Judá que impulsó una reforma religiosa; también un antepasado levita', 'Asa — rey de Judá que impulsó una reforma religiosa; también un antepasado levita');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0611', 'spa', 'Dano grave, desgracia, lesion corporal seria; una calamidad que sobreviene a alguien.', 'Se refiere a un dano fisico grave o una lesion fatal. En la narrativa de Jose, Jacob teme en dos ocasiones que le ''sobrevenga un mal'' a Benjamin durante el viaje a Egipto (Gn 42:4, 38; 44:29), expresando el pavor de un padre ante la posibilidad de perder otro hijo. En el Codigo de la Alianza (Ex 21:22-23), el termino distingue entre una lesion accidental a una mujer embarazada donde no resulta ''dano'' duradero y otra donde si ocurre dano grave, activando la ley del talion. Su campo semantico abarca desde la desgracia hasta la lesion mortal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0612', 'spa', 'Ataduras, prisión (ligaduras físicas o el lugar de confinamiento)', 'Ataduras o cadenas, y por extensión el lugar donde se confina a los presos: la prisión. Jueces lo emplea para las cuerdas que sujetaban a Sansón, las cuales el Espíritu le permitió romper como lino quemado. Eclesiastés lo usa metafóricamente para las manos de la mujer seductora que atrapan al insensato. Jeremías habla de la «casa de las ataduras» como designación de la cárcel. El término abarca tanto la sujeción física como la institución del encarcelamiento, enlazando la cautividad material con la figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0613', 'spa', 'Atadura, banda, prisión (arameo: grillete o confinamiento)', 'Equivalente arameo de la palabra hebrea para ataduras o grilletes, que aparece en la visión de Daniel y en el lenguaje administrativo persa. En el sueño de Nabucodonosor, Daniel describe una banda de hierro y bronce alrededor del tocón de un árbol, simbolizando restricción. Esdras menciona el encarcelamiento como una pena disponible para las autoridades persas. El término arameo conecta la sujeción física con el castigo judicial, donde los grilletes representan tanto el instrumento como el estado de estar preso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0615', 'spa', 'Prisionero o cautivo; persona retenida en cautiverio, ya sea en una mazmorra literal o bajo opresión. Introducido en la narrativa de José (Gn 39:20, 2', 'Prisionero o cautivo; persona retenida en cautiverio, ya sea en una mazmorra literal o bajo opresión. Introducido en la narrativa de José (Gn 39:20, 22), el término aparece después casi exclusivamente en la poesía, donde adquiere profundidad teológica. Los salmistas invocan la compasión de Dios hacia los prisioneros (Sal 69:34; 79:11; 102:21), emparejándolos con los necesitados y los condenados. En Zacarías 9:11 los exiliados liberados de Israel son llamados ''prisioneros de esperanza''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0616', 'spa', 'Prisionero, cautivo; quien está atado o confinado, usado colectivamente para los tomados en guerra o en servidumbre.', 'Sustantivo que significa prisionero o cautivo, empleado frecuentemente de forma colectiva para designar grupos mantenidos en cautiverio o capturados en batalla. Las profecías de Isaías lo usan con gran fuerza: en 10:4 el pueblo se inclinará entre los prisioneros, en 24:22 reyes son reunidos como presos en un calabozo, y en 42:7 el Siervo del Señor sacará a los prisioneros de la mazmorra. El Salmo 79:11 empareja el gemido del prisionero (אֶנְקַת אָסִיר) con una súplica de intervención divina. También puede aparecer como epíteto personal de Jeconías «el cautivo» en 1 Crónicas 3:17.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0617', 'spa', 'Asir — nombre propio que significa ''prisionero,'' llevado por un descendiente levitico de Core y otros en las genealogias de Cronicas.', 'Nombre propio hebreo derivado de la raiz que significa ''atar'' o ''prisionero.'' Asir aparece como hijo de Core en Exodo 6:24 y reaparece en las genealogias leviticas de 1 Cronicas 6, donde tambien se le llama hijo de Ebiasaf. El nombre surge nuevamente en 1 Cronicas 3:17, en la linea real cercana al exilio. Las traducciones al espanol e ingles lo rinden consistentemente como ''Asir/Assir,'' mientras que las versiones en frances y aleman a veces transliteran directamente la forma consonantica hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0621', 'spa', 'Asenat (esposa egipcia de José, posiblemente ''perteneciente a Neit'')', 'La esposa egipcia de José, otorgada a él por Faraón junto con un alto cargo. Su nombre probablemente significa «perteneciente a (la diosa) Neit», reflejando auténticos patrones onomásticos y cultura religiosa egipcia. Como hija de Potifera, sacerdote de On, provenía de la élite sacerdotal de Egipto. A través de ella, José engendró a Efraín y Manasés, lo que significa que la mitad de la estructura tribal de Israel desciende de una madre egipcia. Su presencia en la narrativa subraya cómo los propósitos de Dios incorporaron incluso un linaje egipcio al pueblo del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0622', 'spa', 'Reunir, recoger, congregar; por extensión quitar, retirar; eufemismo para morir (''ser reunido con su pueblo'').', 'Una raíz versátil que aparece en todas las conjugaciones mayores del hebreo. אסף cubre el arco completo desde la recolección física de cosechas o la congregación de personas (Qal/Nifal) hasta el solemne eufemismo de ser ''reunido con los padres'' al morir (Gn 25:8). En Piel adquiere un sentido militar como ''retaguardia'', el que recoge a los rezagados. El Hifil intensifica hacia el barrido profético (Sof 1:2). Un posible homógrafo distinto emerge en 2 Reyes 5, donde Naamán busca a alguien que lo ''recoja'' — es decir, sane — de su lepra, sentido que el árabe يشفي y el suajili kumponya confirman independientemente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0623', 'spa', 'Asaf — ''recolector''; músico levita de la corte de David, ancestro de un gremio de cantores del templo.', 'Asaf — ''recolector''; músico levita de la corte de David, ancestro de un gremio de cantores del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0624', 'spa', 'Almacenes (depósitos para provisiones reunidas)', 'Almacenes o depósitos donde se guardaban provisiones, tesoros o suministros del templo. Crónicas menciona estas estructuras cerca de las puertas del templo, donde los porteros levitas custodiaban las riquezas y ofrendas acumuladas. Nehemías enumera los almacenes entre los puestos donde servían cantores y porteros del templo. Estos edificios representaban la infraestructura organizativa necesaria para el culto sostenido y la vida comunitaria, y requerían personal de confianza para administrar lo reunido para uso sagrado y comunal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0625', 'spa', 'Recolección, cosecha, siega (el acto o la temporada de recoger los frutos)', 'El acto o la temporada de recoger las cosechas, particularmente los frutos de verano. Isaías lo emplea para describir la cosecha esperada que no llegará, y metafóricamente para un ejército destructor que devora como langostas que arrasan todo a su paso. Miqueas lamenta no hallar fruto en el tiempo de la recolección. El término enfatiza la acción y el momento de la cosecha más que el resultado almacenado, capturando ese instante crítico en que el trabajo agrícola alcanza su fruto o, desgarradoramente, fracasa en producirlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0629', 'spa', 'Cabalmente, con toda diligencia; adverbio arameo que denota completitud y ejecución cuidadosa de decretos oficiales.', 'Adverbio arameo que aparece exclusivamente en el libro de Esdras, empleado en el contexto de la correspondencia imperial persa para expresar que algo debe hacerse con esmero y plena diligencia. Aparece en decretos reales relativos a la reconstrucción del templo de Jerusalén (Esd 5:8; 6:8, 12-13) y en la comisión de Artajerjes a Esdras (7:17, 21, 26). La palabra deriva de raíces del persa antiguo que significan ''completo'' o ''correcto'', reflejando la precisión administrativa de la burocracia persa que gobernaba Judá durante el período del Segundo Templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0631', 'spa', 'Atar, ligar, aprisionar; obligar mediante un voto; enganchar animales; como sustantivo, un prisionero o cautivo.', 'Atar, ligar, aprisionar; obligar mediante un voto; enganchar animales; como sustantivo, un prisionero o cautivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0632', 'spa', 'Vínculo, obligación jurada — un voto solemne o restricción autoimpuesta, usado exclusivamente para el voto de una mujer sujeto a la autoridad paterna ', 'Vínculo, obligación jurada — un voto solemne o restricción autoimpuesta, usado exclusivamente para el voto de una mujer sujeto a la autoridad paterna o marital. El sustantivo אִסָּר (isar) designa una obligación vinculante o restricción jurada que uno se impone a sí mismo, y aparece exclusivamente en la legislación de Números 30 concerniente a los votos de las mujeres. El capítulo distingue entre un néder (voto de hacer algo) y un isar (un vínculo de abnegación — una obligación de abstenerse). El isar de una mujer joven puede ser anulado por su padre el día que lo oye (Nm 30:4-5), y el isar de una mujer casada puede ser anulado o ratificado por su esposo (Nm 30:7-8, 10-13). La palabra deriva de la raíz אסר (''atar, ligar''), enfatizando el carácter restrictivo y obligatorio del compromiso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0633', 'spa', 'Interdicto o decreto vinculante; término legal arameo para una prohibición real irrevocable, usado solo en Daniel 6.', 'Sustantivo masculino arameo que significa ''interdicto'' o ''decreto vinculante'', derivado de la raíz que significa ''atar''. Aparece únicamente en Daniel 6 en relación con el decreto tramado por los funcionarios de Darío para tender una trampa a Daniel: una ley de medos y persas que no podía ser revocada. La palabra transmite la fuerza de algo que obliga o constriñe legalmente, subrayando la naturaleza irrevocable del edicto. Sus siete apariciones se concentran en una sola narrativa dramática, resaltando la trampa legal ineludible tendida contra la fiel vida de oración de Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0634', 'spa', 'Esar-hadón — rey asirio (681–669 a.C.), hijo de Senaquerib, que reasentó pueblos en Samaria.', 'Esar-hadón (acadio Aššur-aḫu-iddina, ''Asur ha dado un hermano'') fue el rey de Asiria que reinó del 681 al 669 a.C. Llegó al poder tras el asesinato de su padre Senaquerib a manos de dos de sus propios hijos (2 R 19:37 = Is 37:38), cumplimiento dramático de la profecía de Isaías. Esdras 4:2 registra que los colonos samaritanos que se oponían a la reconstrucción del templo de Jerusalén afirmaban haber sido reasentados por Esar-hadón, un detalle que ancla el conflicto postexílico en la política imperial asiria. El nombre aparece consistentemente en su forma hebraizada bipartita en todas las ocurrencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0635', 'spa', 'Ester — la reina judía de Persia, heroína del libro que lleva su nombre, también conocida como Hadasa', 'Ester — la reina judía de Persia, heroína del libro que lleva su nombre, también conocida como Hadasa');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0636', 'spa', 'Madera, viga o madero — sustantivo arameo para la madera usada en construccion o como material de idolos.', 'Sustantivo arameo que corresponde al hebreo עֵץ (madera/arbol), apareciendo exclusivamente en las secciones arameas de Esdras y Daniel. En Esdras 5:8 y 6:4 designa madera de construccion y vigas empleadas en la reconstruccion del templo de Jerusalen, mientras que en Esdras 6:11 se refiere a una viga de una casa demolida usada como castigo. En Daniel 5:4 y 5:23 la forma enfatica senala el material de los idolos paganos: dioses ''de oro, plata, bronce, hierro, madera y piedra.'' El espanol ''madera'' capta bien el sentido generico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0637', 'spa', 'También, ciertamente, aun, sí; conjunción enfática que añade fuerza, marca inclusión o introduce argumentos a fortiori.', 'Una de las partículas retóricas más versátiles del hebreo, אַף funciona como intensificador que añade peso dondequiera que aparece. Puede significar simplemente ''también'' (Gn 40:16), pero regularmente escala a ''ciertamente, en verdad'' al encabezar declaraciones enfáticas en poesía (Sal 16:6-9). En la argumentación impulsa el patrón del קַל וָחֹמֶר (''cuánto más/menos'') tan apreciado por el razonamiento bíblico y rabínico (1 S 14:30; 2 S 16:11). Aunque la prosa prefiere גַּם para la simple adición, אַף es la herramienta predilecta del poeta y el orador para el impacto retórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0638', 'spa', 'También, aun, además (conjunción aramea que añade énfasis o inclusión a una cláusula).', 'Conjunción aramea que significa «también» o «aun», que aparece siempre en la forma combinada וְאַף («y también»). Funciona como partícula aditiva y a veces intensificadora en las porciones arameas de Esdras y Daniel. Es cognada del hebreo אַף y está atestiguada en el arameo egipcio y palmireno, perteneciendo al acervo semítico común de partículas enfáticas. Las cuatro ocurrencias refuerzan o amplían una declaración precedente, como cuando Daniel 6:22 reporta que «también ante ti, oh rey, no he cometido falta alguna».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0639', 'spa', 'Nariz, rostro; por metonimia ira o furor; en la expresión idiomática אֶרֶךְ אַפַּיִם, ''tardo para la ira''.', 'Pocas palabras hebreas ilustran la transición del cuerpo a la emoción tan vívidamente como אַף. Comienza con la nariz física — el órgano por el cual Dios sopla vida en Adán (Gn 2:7) y por el cual sale el viento ardiente de la furia divina (Éx 15:8). De las narices dilatadas, la palabra se desliza hacia ''ira'', su sentido más frecuente, apareciendo en la frase חֲרוֹן אַף (''ardor de ira'') más de cuarenta veces. La forma dual אַפַּיִם puede significar ''rostro'' o funcionar en la gran autodescripción divina אֶרֶךְ אַפַּיִם — ''tardo para la ira'', literalmente ''largo de narices'', revelada en Sinaí (Éx 34:6) y repetida en Salmos, Profetas y Sabiduría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0642', 'spa', 'efod, banda del efod, revestimiento (prenda sacerdotal o cobertura de ídolos con materiales preciosos)', 'Término relacionado con el efod sacerdotal, que designa específicamente su banda hábilmente tejida o el revestimiento de ídolos con materiales preciosos. En Éxodo se refiere al cinto del efod del sumo sacerdote que sujetaba la vestidura. En Isaías describe la cobertura de oro con que se recubrían las imágenes fundidas, en paralelo con el enchapado de plata de los ídolos tallados. La palabra comparte raíz con «efod» pero aporta las formas constructas y con sufijo, extendiéndose metafóricamente a cualquier «revestimiento» o «envoltura» que adorna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0644', 'spa', 'Hornear; panadero (como sustantivo agente); ser horneado (pasivo)', 'Hornear; panadero (como sustantivo agente); ser horneado (pasivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0645', 'spa', 'Entonces, pues — partícula enclítica enfática usada en preguntas e inferencias. Añade urgencia o énfasis de modo similar al español ''entonces'' en ''¿qu', 'Entonces, pues — partícula enclítica enfática usada en preguntas e inferencias. Añade urgencia o énfasis de modo similar al español ''entonces'' en ''¿quién fue entonces?''. La pregunta temblorosa de Isaac מִי אֵפוֹא (''¿quién entonces?'', Gn 27:33) al descubrir el engaño de Jacob es su aparición más dramática. En Job puntúa razonamientos angustiosos: ''¿dónde está entonces mi esperanza?'' (17:15). También aparece en contextos deliberativos: ''si así ha de ser, entonces haced esto'' (Gn 43:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0646', 'spa', 'Efod — vestidura sacerdotal que se lleva sobre los hombros, utilizada en el culto y la consulta oracular', 'Efod — vestidura sacerdotal que se lleva sobre los hombros, utilizada en el culto y la consulta oracular');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0650', 'spa', 'Canal, cauce, lecho de arroyo (wadi o barranco); tubo o conducto (de huesos/escamas); uno fuerte o poderoso', 'Canal, cauce, lecho de arroyo (wadi o barranco); tubo o conducto (de huesos/escamas); uno fuerte o poderoso');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0652', 'spa', 'Oscuridad profunda, tiniebla densa; voz poética para la oscuridad cósmica, existencial o catastrófica.', 'Sustantivo poético que evoca una oscuridad profunda e impenetrable, más allá del simple anochecer. Aparece exclusivamente en contextos literarios elevados — Job y los Salmos — para describir la tiniebla primordial que se apodera de una noche maldita (Job 3:6), la lobreguez asfixiante del Seol (Job 10:22) y la ceguera espiritual de la que Dios libera (Isa 29:18). A menudo se presenta junto a חֹשֶׁךְ (oscuridad) y צַלְמָוֶת (sombra de muerte), formando un vocabulario escalonado de penumbra y espanto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0653', 'spa', 'Oscuridad, tinieblas densas; tanto oscuridad física espesa (plaga, noche, Día de YHWH) como oscuridad figurada de calamidad y juicio.', 'Oscuridad, tinieblas densas; tanto oscuridad física espesa (plaga, noche, Día de YHWH) como oscuridad figurada de calamidad y juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0656', 'spa', 'Cesar, acabarse o agotarse: se dice de recursos que se agotan, opresores que perecen y la misericordia divina que parece detenerse.', 'Verbo que aparece exclusivamente en Qal perfecto tercera persona masculino singular, y transmite la idea de que algo llega a su fin o queda completamente agotado. En Gn 47:15-16 describe cómo el dinero se acabó durante la hambruna en Egipto, mientras que en Is 16:4 y 29:20 anuncia el fin de opresores y tiranos, emparejado con sinónimos de destrucción (כָּלָה, תָּמַם). En el Sal 77:8 el salmista pregunta con angustia si la misericordia de Dios ha cesado para siempre, usando la fuerza interrogativa que el español capta bien con «¿Acaso cesó?».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0657a', 'spa', 'Fin, extremo; nada, inexistencia; partícula adversativa ''sin embargo, pero''; privativo ''sin, por falta de''.', 'Fin, extremo; nada, inexistencia; partícula adversativa ''sin embargo, pero''; privativo ''sin, por falta de''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0660', 'spa', 'víbora, áspid (serpiente venenosa)', 'Serpiente venenosa, muy probablemente una víbora o áspid, cuyo nombre quizá derive del sonido de su siseo. Isaías emplea el término en profecías de juicio y peligro, describiendo huevos de víbora y la naturaleza letal de la maldad. Job lo utiliza en la advertencia de Bildad de que el impío «chupará veneno de víboras» y la lengua de la víbora lo matará. Esta serpiente encarna el peligro mortal que acecha en lugares aparentemente seguros, una metáfora natural de la naturaleza engañosa y mortífera del pecado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0661', 'spa', 'Rodear, envolver o engullir: verbo poético para ser cercado por aguas, muerte o calamidades.', 'Verbo poético usado exclusivamente para describir la experiencia de ser abrumado o rodeado por fuerzas mortíferas. En sentido literal, retrata las aguas cerrándose sobre Jonás (2:5); en sentido figurado, describe los «torrentes de la muerte» o «cuerdas de la muerte» envolviendo al hablante en 2 S 22:5, Sal 18:4 y Sal 116:3. En el Sal 40:12 son los males los que rodean al salmista. Cada aparición transmite una sensación visceral de peligro cerrándose desde todos los flancos, con una imagen de inmersión total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0662', 'spa', 'Contenerse, reprimirse, ejercer dominio propio; Hitpael de אפק, describe la contención forzada de emociones intensas.', 'Verbo en la conjugación Hitpael (reflexiva) que significa contenerse o dominarse, especialmente cuando se está abrumado por emociones fuertes. Los ejemplos más vívidos son la lucha desesperada de José por contener el llanto ante sus hermanos (Gn 43:31; 45:1). También describe la fatídica decisión de Saúl de forzarse a actuar en Gilgal (1 S 13:12), a Amán tragándose su ira (Est 5:10) y, de manera notable, a Dios mismo conteniendo Su propio poder (Is 42:14) o Su compasión siendo refrenada hacia Israel (Is 63:15; 64:11). El espectro abarca desde la lucha emocional humana hasta la autocontención divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0663', 'spa', 'Afec, topónimo cananeo que significa ''recinto'' o ''fortaleza'', aplicado a varias ciudades en Israel.', 'Nombre de lugar que designa al menos cuatro sitios distintos en la tierra de Israel, todos probablemente posiciones fortificadas — el propio nombre podría derivar de una raíz que significa ''ser fuerte'' o ''encerrar''. El Afec de mayor importancia militar se halla cerca del valle de Jezreel, donde arameos e israelitas se enfrentaron (1 Re 20:26, 30; 2 Re 13:17). Otro Afec en la llanura filistea fue escenario de la captura del arca de la alianza (1 Sam 4:1; 29:1). Otros sitios aparecen en Aser (Jos 19:30; Jue 1:31) y al noreste de Beirut (Jos 13:4). Todas las tradiciones de traducción conservan el nombre de forma fonética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0665', 'spa', 'Ceniza; residuo en polvo de la combustión, usado ritualmente para purificación y como señal de duelo o humildad.', 'Ceniza; residuo en polvo de la combustión, usado ritualmente para purificación y como señal de duelo o humildad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0667', 'spa', 'Polluelo, cría o pichón: la cría de las aves, usada en leyes de compasión e imágenes poéticas.', 'Sustantivo que designa a las crías de las aves, presente en contextos que van desde la legislación de la Torá hasta la poesía sapiencial. En Dt 22:6 aparece dos veces en la ley que prohíbe tomar a la madre junto con sus polluelos, mandamiento asociado con la compasión y la longevidad. En Job 39:30 describe las crías del águila o buitre que lamen sangre, mostrando que el término no se limita a aves domésticas. En el Sal 84:3 los pichones de la golondrina hallan refugio junto al altar de Dios. El cognado etíope confirma el significado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0669', 'spa', 'Efraín — el hijo menor de José, la tribu israelita descendiente de él y su territorio asignado.', 'Efraín es uno de los nombres propios de mayor estratificación en la Biblia hebrea, deslizándose fluidamente entre persona, tribu y territorio. José nombra a su segundo hijo אֶפְרַיִם (''doblemente fructífero'') en Egipto (Gn 41:52), y la bendición deliberada de Jacob sobre Efraín por encima del primogénito Manasés (Gn 48:14) prefigura el dominio político de la tribu. La serranía de Efraín se convierte en el corazón del reino del norte, y proféticamente ''Efraín'' a menudo representa a todas las tribus septentrionales de Israel (Os 5-14). Español ''Efraín'', francés ''Ephraim'' y alemán ''Efrajim'' reflejan adaptaciones fonológicas menores del mismo nombre hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0672', 'spa', 'Efrata — región cercana a Belén; asociada con la sepultura de Raquel y el lugar de nacimiento del Mesías (Miq 5:2).', 'Efrata — región cercana a Belén; asociada con la sepultura de Raquel y el lugar de nacimiento del Mesías (Miq 5:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0673', 'spa', 'Efrateo: gentilicio que designa a un efraimita (de la tribu de Efraín) o a un efrateo (de Efrata/Belén).', 'Adjetivo gentilicio con dos referentes distintos según el contexto. Cuando se aplica a personajes de la región montañosa de Efraín, como Jeroboam (1 R 11:26) o el ancestro de Elcana (1 S 1:1), significa ''efraimita'', miembro de la tribu de Efraín. Cuando aparece acompañado de ''de Belén'', como en el caso de Isaí (1 S 17:12) y la familia de Elimelec (Rut 1:2), significa ''efrateo'', indicando procedencia de Efrata-Belén en Judá. El francés distingue entre ''Éphraïmite'' y ''Éphratien'', mientras que el español suele usar ''efrateo'' para ambos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0676', 'spa', 'Dedo de la mano o del pie; un dígito usado especialmente en contextos rituales y divinos, o raramente referido al pie.', 'Dedo de la mano o del pie; un dígito usado especialmente en contextos rituales y divinos, o raramente referido al pie.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0677', 'spa', 'dedos (arameo: extremidades de manos y pies)', 'Término arameo para dedos de las manos o de los pies, que aparece en las visiones y revelaciones de Daniel. Daniel ve unos dedos misteriosos que escriben en la pared del palacio durante el banquete de Belsasar, y la estatua compuesta del sueño de Nabucodonosor tiene pies en parte de hierro y en parte de barro, extendiéndose hasta los dedos de los pies. La forma plural abarca tanto los dedos de las manos como los de los pies, y el contexto determina cuál se indica. Estas extremidades representan tanto la acción divina sobrenatural (los dedos que escriben) como la debilidad estructural (los dedos de material mixto que sostienen un imperio).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0679', 'spa', 'articulaciones, codos, coyunturas de los brazos (puntos de articulación anatómica)', 'Las articulaciones donde se unen los miembros, particularmente codos o coyunturas del brazo. Ezequiel emplea el término para «coyunturas de las manos» (codos) al describir las bandas mágicas que las falsas profetisas cosían en cada articulación del brazo. Jeremías lo usa cuando instruye a Ebed-melec a colocar trapos bajo «las coyunturas de sus brazos» (axilas) antes de izarlo de la cisterna. El sentido anatómico técnico se extiende metafóricamente a «uniones» arquitectónicas. El término subraya el punto de articulación donde se encuentran la flexibilidad y la estructura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0680', 'spa', 'Apartar, reservar, retirar o retener: se dice de reservar bendiciones, separar espíritu y negar placeres.', 'Verbo cuyo campo semántico abarca desde ''reservar'' hasta ''retirar'' y ''retener'', y aparece en contextos narrativos diversos. En Gn 27:36 Esaú suplica a Isaac preguntándole si no ha reservado una bendición para él. Nm 11:17 y 11:25 describen a Dios tomando parte del espíritu que reposaba sobre Moisés para repartirlo entre los setenta ancianos. En Ec 2:10 el Predicador dice que no les negó nada a sus ojos. Ez 42:6 emplea el Nifal para describir un estrechamiento arquitectónico. La idea central es separar una porción de un todo mayor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0681', 'spa', 'Preposición sustantivada que significa ''junto a, cerca de, al lado de''; con prefijo מִן, ''de junto a, lejos de la cercanía de''.', 'Preposición sustantivada que significa ''junto a, cerca de, al lado de''; con prefijo מִן, ''de junto a, lejos de la cercanía de''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0682a', 'spa', 'Azel — nombre propio de un descendiente benjaminita de Saúl por la línea de Jonatán.', 'Azel (אָצֵל) es un nombre propio masculino que aparece exclusivamente en la genealogía saulida de 1 Crónicas 8:37-38 y su paralelo en 9:43-44. Fue descendiente del rey Saúl por la línea de Jonatán, y el texto señala que tuvo seis hijos cuyos nombres se enumeran. El nombre podría derivar de una raíz que significa ''noble'' (cf. אָצִיל), aunque su etimología permanece incierta. El contexto genealógico sitúa a Azel varias generaciones después de Jonatán, en el período de la monarquía dividida o posterior. BDB también registra un topónimo distinto Azel en Zacarías 14:5, que pertenece a otra entrada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0686', 'spa', 'Atesorar, almacenar o acumular; por extension denominativa, designar tesoreros sobre un deposito.', 'Verbo arraigado en la idea de reunir y guardar en un deposito o almacen. En 2 Reyes 20:17 e Isaias 39:6 se advierte a Ezequias que todo lo que sus padres atesoraron sera llevado a Babilonia. Amos 3:10 acusa a los poderosos de acumular violencia y despojo en sus palacios, una llamativa extension metaforica. Isaias 23:18 contempla que la mercancia de Tiro ya no sera atesorada, sino que fluira hacia quienes habitan ante el Senor. En Nehemias 13:13 el Hifil se emplea denominativamente con el sentido de ''designar como tesoreros''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0687', 'spa', 'Etser -- jefe horita, hijo de Seir, cuyo nombre puede significar ''tesoro'' o ''pacto''.', 'Nombre propio de un jefe de clan horita incluido entre los hijos de Seir en las genealogias de Genesis 36 y 1 Cronicas 1. El nombre probablemente deriva de la raiz que significa ''almacenar'' o ''tesoro'', aunque BDB tambien senala el cognado arabe con sentido de ''pacto'' o ''vinculo''. Etser aparece en Genesis 36:21 entre los jefes horitas de la tierra de Edom, con sus propios hijos listados en 36:27 y su jefatura confirmada en 36:30. Los pasajes paralelos de 1 Cronicas 1:38 y 1:42 reproducen los mismos datos genealogicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0692', 'spa', 'Areli, arelita (nombre de clan gadita y su gentilicio)', 'Nombre de un hijo de Gad y la designación del clan correspondiente. El nombre posiblemente derive de la misma raíz que Ariel, quizá con el significado de «león de Dios» o relacionado con la imagen del altar-hogar, aunque su significado preciso es incierto. Génesis conserva el nombre personal en las listas de clanes, mientras que Números ofrece tanto el nombre individual como la designación familiar. El registro de la identidad tribal era de suma importancia para la herencia y la pertenencia comunitaria, lo que hace que incluso breves noticias genealógicas sean significativas para preservar la estructura de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0693', 'spa', 'Acechar, emboscar; ocultarse con intención hostil, o el grupo de emboscada en sí mismo.', 'Acechar, emboscar; ocultarse con intención hostil, o el grupo de emboscada en sí mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0697', 'spa', 'Langosta -- el saltamontes migratorio que forma enjambres, devastador de cultivos y figura de ejércitos invasores', 'Langosta -- el saltamontes migratorio que forma enjambres, devastador de cultivos y figura de ejércitos invasores');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0699', 'spa', 'Ventana enrejada o abertura; usado figuradamente para las compuertas del cielo por donde se derrama lluvia y bendición.', 'Designa una abertura o ventana enrejada en una estructura, como una chimenea para el humo (Os 13:3) o las aberturas de un palomar (Isa 60:8). Su uso más memorable es la expresión ''ventanas del cielo'' (Gn 7:11; 8:2), por las cuales Dios desata el diluvio o derrama bendición (Mal 3:10). Las traducciones al español emplean consistentemente la imagen de ''ventana'' o ''compuerta''. En Eclesiastés 12:3, la extensión metafórica compara la vista que se debilita con ventanas enrejadas que se van oscureciendo, evocando así el deterioro del cuerpo humano con la vejez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0702', 'spa', 'Cuatro; el número cardinal, que también forma el compuesto ''catorce'' al combinarse con la palabra para diez.', 'El numeral hebreo para cuatro aparece en todos los géneros de las Escrituras: genealogías, medidas, descripciones geográficas y calendarios rituales. Sus 320 ocurrencias se dividen naturalmente entre usos independientes (277 veces) y usos compuestos como parte de ''catorce'' (43 veces). Todas las lenguas meta traducen con su numeral básico para cuatro — árabe أربع, español ''cuatro'', francés ''quatre'', alemán ''vier'' — mientras que el compuesto catorce genera formas compuestas propias de cada lengua. Los ''cuatro ríos'' del Edén (Gn 2:10) y la fecha de Pascua del día decimocuarto (Éx 12:6) figuran entre sus apariciones más memorables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0703', 'spa', 'Cuatro — el número cardinal, usado para contar y en numerales compuestos.', 'El número cardinal cuatro (אַרְבַּע en femenino / אַרְבְּעָה en masculino) es uno de los numerales más frecuentes en las Escrituras. En los pasajes de Daniel y Esdras donde se concentra este lema, cuenta bestias en visión apocalíptica (Dn 7:2, 3, 6, 17), hombres caminando en el horno de fuego (Dn 3:25) y animales sacrificiales (Esd 6:17, ''cuatrocientos''). Toda tradición de traducción lo vierte con el simple numeral — ''cuatro'' en español, ''quatre'' en francés — confirmando su función puramente cuantitativa e inequívoca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0704', 'spa', 'Quiriat-arba, nombre antiguo de Hebrón; posiblemente significa ''ciudad de cuatro'' o lleva el nombre de Arba', 'Esta antigua designación de Hebrón aparece principalmente en las narrativas sacerdotales y de la conquista temprana. El significado del nombre permanece incierto: puede ser ''ciudad de cuatro'', quizá en referencia a cuatro barrios o clanes, o puede conservar el nombre de un antepasado anterior de los anaceos llamado Arba. Sara murió aquí y Abraham compró la cueva de Macpela para su sepultura. Los israelitas la renombraron Hebrón, aunque los escritores bíblicos ocasionalmente conservan el nombre más antiguo para subrayar la antigüedad de la ciudad. Esta doble denominación funciona como recurso literario que conecta las promesas patriarcales con el cumplimiento de la conquista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0705', 'spa', 'Cuarenta — numeral cardinal que significa una generación, un período de prueba o un lapso completo de juicio en las Escrituras.', 'אַרְבָּעִים es el numeral hebreo indeclinable para cuarenta, con 135 ocurrencias y uno de los números con mayor carga simbólica en la Biblia. Israel vagó cuarenta años por el desierto (Nm 14:33-34; Dt 8:2), Moisés pasó cuarenta días en el Sinaí (Éx 24:18; 34:28), Elías caminó cuarenta días hasta Horeb (1 R 19:8) y Nínive recibió cuarenta días de aviso de juicio (Jon 3:4). El número acompaña frecuentemente a los sustantivos שָׁנָה (''año'') e יוֹם (''día''), creando fórmulas que se convirtieron en abreviatura de intervalos divinamente señalados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0707', 'spa', 'Tejer tela o tejido; también usado sustantivamente para referirse al tejedor o al oficio de tejer. El participio funciona frecuentemente como sustanti', 'Tejer tela o tejido; también usado sustantivamente para referirse al tejedor o al oficio de tejer. El participio funciona frecuentemente como sustantivo (''tejedor''), y la expresión ''enjullo de tejedor'' se convirtió en un modismo estándar para describir un asta de lanza enorme (1 S 17:7; 2 S 21:19). El término abarca tanto la producción textil literal — obreros egipcios del lino en Isaías 19:9, artesanos de cortinas del templo en Éxodo 28:32 y 35:35 — como la intriga metafórica, como en Isaías 59:5 donde los malvados ''tejen telas de araña''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0709', 'spa', 'Argob -- region definida en Basan, asociada con sesenta ciudades fortificadas y los asentamientos de Jair.', 'Toponimo que designa un distrito especifico dentro del territorio de Basan en Transjordania, mencionado sistematicamente junto con חֶבֶל (region o porcion medida). El nombre posiblemente derive de una raiz que significa ''monton'' o ''terron'', aludiendo al terreno volcanico de la zona. En Deuteronomio 3:4, 13-14 es la region de sesenta ciudades fortificadas conquistada por los israelitas y asignada a la media tribu de Manases, vinculada a Jair hijo de Manases. En 1 Reyes 4:13 forma parte del distrito administrativo de Ben-Gueber. La referencia problematica de 2 Reyes 15:25 aparece en el contexto de una conspiracion palaciega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0711', 'spa', 'Púrpura (arameo: tinte o tela púrpura, color asociado a la realeza)', 'Término arameo que designa el tinte o la tela de color púrpura, un artículo de lujo vinculado a la realeza. Daniel emplea esta palabra al describir los honores prometidos a quien pudiera interpretar la escritura en la pared: ser vestido de púrpura junto con un collar de oro. El tinte púrpura, extraído de moluscos del Mediterráneo, era extraordinariamente costoso, por lo que su uso quedaba reservado a la realeza y la élite adinerada. Este color simbolizaba poder, prestigio y privilegio en todas las culturas del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0712', 'spa', 'Caja, cofre, arca (recipiente para objetos sagrados o valiosos)', 'Una caja o cofre utilizado para transportar objetos sagrados, mencionado específicamente en el relato de la devolución del arca del pacto a Israel. Los filisteos colocaron su ofrenda por la culpa —figuras de oro en forma de tumores y ratones— en este recipiente junto al arca. El término puede relacionarse con un movimiento de balanceo, describiendo quizá cómo se transportaban o aseguraban dichas cajas. El contexto narrativo resalta el cuidado en el manejo de las cosas santas, incluso por parte de quienes no adoraban al Dios de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0713', 'spa', 'Tela o tinte púrpura — textil costoso derivado del múrice, usado en los enseres del tabernáculo, vestiduras sacerdotales y atuendo real.', 'Tela o tinte púrpura — textil costoso derivado del múrice, usado en los enseres del tabernáculo, vestiduras sacerdotales y atuendo real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0718', 'spa', 'Interjeccion aramea ''!he aqui!'' usada para introducir visiones dramaticas, especialmente en la imagineria apocaliptica de Daniel.', 'Exclamacion aramea que significa ''!he aqui!'' o ''!mira!'', empleada exclusivamente en las visiones nocturnas de Daniel para dirigir la atencion hacia cada nueva figura simbolica que surge ante los ojos del profeta. Todas las apariciones siguen el patron formulario ''y he aqui'' (וַאֲרוּ), marcando la revelacion dramatica de las bestias sucesivas y del Hijo del Hombre en Daniel 7. El espanol ''he aqui'' capta bien su fuerza deictica, senalando hacia algo sorprendente y recien visible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0723', 'spa', 'Establos, pesebres (comederos o recintos para animales de ganado)', 'Establos o pesebres para el ganado, particularmente caballos. El término aparece en las descripciones de las extensas caballerizas de Salomón y en contextos de almacenamiento agrícola. Reyes y Crónicas registran miles de establos para los caballos y carros de Salomón, indicando tanto poderío militar como organización administrativa. Una referencia adicional en Crónicas habla de almacenes y establos para diversos animales, evidenciando la infraestructura de riqueza agrícola. Este préstamo arameo refleja el contacto cultural en el vocabulario de la ganadería.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0724', 'spa', 'Sanidad, restauración; literalmente ''carne nueva sobre una herida'', usado figuradamente para la recuperación nacional y espiritual.', 'Sustantivo femenino que significa sanidad o restauración, derivado de la imagen de carne nueva que crece sobre una herida. Aparece exclusivamente en contextos figurados que describen la recuperación nacional. Isaías 58:8 promete que la ''sanidad'' de Israel brotará prontamente cuando practiquen la verdadera justicia, emparejado con el verbo ''brotar'' (צָמַח), evocando un crecimiento orgánico. Jeremías lo usa tres veces: cuestionando si el bálsamo de Galaad puede traer sanidad (8:22), prometiendo que Dios restaurará la salud de Israel herido (30:17; 33:6). En el período postexílico describe la restauración física de los muros del templo (2 Cr 24:13) y de las murallas de Jerusalén (Neh 4:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0727', 'spa', 'Cofre o arca; el Arca del Pacto, un cofre de recolección de dinero, o un ataúd para sepultura.', 'Término notablemente versátil para designar un receptáculo rectangular. Aparece de manera abrumadora como el Arca del Pacto, el cofre sagrado que albergaba las tablas de la Ley, transportado por los levitas a través del desierto y finalmente colocado en el templo de Salomón. La misma palabra sirve para el cofre de recolección que Joiada instaló junto al altar para las reparaciones del templo (2 Re 12:10), y en un uso singular y conmovedor, para el ataúd en que fue depositado el cuerpo embalsamado de José en Egipto (Gn 50:26). Los cognados en fenicio, arameo, asirio y árabe apuntan todos a un significado básico de ''cofre'' o ''caja'', lo cual muestra que la connotación sagrada fue un desarrollo israelita superpuesto a una palabra cotidiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0728', 'spa', 'Arauna — un jebuseo propietario de tierras cuya era David compró como sitio para el futuro templo de Jerusalén.', 'Arauna — un jebuseo propietario de tierras cuya era David compró como sitio para el futuro templo de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0730', 'spa', 'Cedro — el árbol del cedro (Cedrus libani), célebre por su altura, fragancia y madera preciada; símbolo de majestad y orgullo.', 'Cedro — el árbol del cedro (Cedrus libani), célebre por su altura, fragancia y madera preciada; símbolo de majestad y orgullo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0732', 'spa', 'Vagar o viajar; como participio, un viajero o caminante de paso sin lazos permanentes.', 'Verbo que significa viajar, caminar o recorrer un sendero, cuya forma participial funciona como sustantivo para designar a un viajero o caminante. En Jueces 19:17 el participio describe a un hombre que transita por Guibea, mientras que en 2 Samuel 12:4 la parabola de Natan contrasta al viajero (אֹרֵחַ) con el anfitirion establecido, distincion que el espanol preserva con ''el viajero''. Jeremias 14:8 pregunta conmovedoramente por que Dios habria de ser como un caminante que solo se detiene a pernoctar, y Job 34:8 emplea el verbo figuradamente para indicar que alguien anda en compania de malhechores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0733', 'spa', 'Ara; nombre propio de un líder de clan aserita y de una familia de exiliados que regresaron.', 'Nombre propio que posiblemente significa «viajero» o «caminante», llevado por al menos dos individuos en el Antiguo Testamento. El primero es un hombre de la tribu de Aser mencionado en la genealogía de 1 Crónicas 7:39. El segundo encabeza una familia de exiliados que regresaron, contados en 775 según Esdras 2:5 y en 652 según Nehemías 7:10, una discrepancia común en los registros censales postexílicos. Nehemías 6:18 posiblemente hace referencia a la misma familia a través de un vínculo matrimonial con Tobías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0734', 'spa', 'Senda o camino, en sentido literal o figurado; modo de vida, conducta moral; viajero o caravana (por metonimia).', 'Senda o camino, en sentido literal o figurado; modo de vida, conducta moral; viajero o caravana (por metonimia).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0737', 'spa', 'Porción o ración de alimento, especialmente una provisión regular; también una comida en sentido general.', 'Designa una porción medida de alimento, generalmente una ración oficial otorgada de forma regular. Su uso más conmovedor describe la ración diaria que Evil-Merodac, rey de Babilonia, concedió al cautivo rey Joaquín: una ''ración continua'' (אֲרֻחָה תָּמִיד, 2 R 25:30; Jer 52:34), un tenue destello de gracia al cierre del relato del exilio. En Jer 40:5, Gedalías recibe una provisión similar. Proverbios 15:17 emplea la palabra de modo distinto para una humilde comida doméstica: ''mejor es una comida de legumbres donde hay amor'' que un buey engordado con odio. El español distingue útilmente entre ''ración/provisiones'' para el sentido oficial y ''comida'' para el ámbito doméstico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0738a', 'spa', 'León; gran felino depredador que simboliza fuerza, realeza, valentía y juicio divino.', 'León; gran felino depredador que simboliza fuerza, realeza, valentía y juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0738b', 'spa', 'León — el león asiático como depredador, símbolo real y metáfora de poder, valentía y juicio divino.', 'León — el león asiático como depredador, símbolo real y metáfora de poder, valentía y juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0740', 'spa', 'Ariel — ''león de Dios''; nombre profético de Jerusalén, también nombre personal y posible término para el altar.', 'Ariel es un nombre de rica densidad semántica que significa ''león de Dios'' (o posiblemente ''hogar de Dios''). Isaías 29:1-7 lo emplea como designación poética de Jerusalén, la ciudad donde acampó David, con Dios advirtiendo que sitiará a Ariel hasta que se convierta en un verdadero altar-hogar, un devastador juego de palabras que conecta el orgulloso nombre de la ciudad con los fuegos del juicio. En Esdras 8:16, Ariel es simplemente un nombre personal, uno de los hombres principales que Esdras convocó para reclutar levitas para el viaje a Jerusalén. La doble significación — orgullo cívico y fuego sacrificial — hace de este uno de los nombres propios de mayor carga teológica en la Biblia hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0741', 'spa', 'Hogar del altar (la plataforma superior del altar donde ardía el fuego sacrificial)', 'El hogar o superficie superior del altar en la visión del templo de Ezequiel. El término presenta variantes ortográficas (ketiv/qeré) y podría significar «hogar de El/Dios» o derivarse de una raíz que significa «león de Dios». Ezequiel describe con precisión arquitectónica los componentes del altar, y este vocablo designa la plataforma superior donde los fuegos sacrificiales consumían las ofrendas. El juego de palabras entre león y hogar podría evocar el poder consumidor del altar, que devora los sacrificios como un león.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0744', 'spa', 'León (arameo) — el gran felino depredador, presente en la narrativa del foso de los leones de Daniel y en visiones apocalípticas.', 'León (arameo) — el gran felino depredador, presente en la narrativa del foso de los leones de Daniel y en visiones apocalípticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0746b', 'spa', 'Arioc, capitán de la guardia real de Nabucodonosor en el libro de Daniel.', 'Nombre propio babilónico que identifica al capitán de la guardia personal del rey Nabucodonosor. Arioc aparece exclusivamente en Daniel 2, donde recibe la orden de ejecutar a los sabios de Babilonia, pero en su lugar lleva a Daniel ante el rey después de que el profeta se ofrece a interpretar el sueño real. Las cinco apariciones del nombre se concentran en un solo episodio (Dn 2:14-25), lo que hace de Arioc una figura narrativa menor pero decisiva que facilita el acceso de Daniel al trono.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0748', 'spa', 'Ser largo, prolongar; extender en tiempo o espacio — especialmente alargar días, estirar cuerdas o demorar una acción.', 'Ser largo, prolongar; extender en tiempo o espacio — especialmente alargar días, estirar cuerdas o demorar una acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0750', 'spa', 'Largo, lento (referido a la ira); longánimo, paciente — adjetivo que describe tolerancia o extensión física. Aparece casi exclusivamente en la frase c', 'Largo, lento (referido a la ira); longánimo, paciente — adjetivo que describe tolerancia o extensión física. Aparece casi exclusivamente en la frase constructa אֶרֶךְ אַפַּיִם, literalmente ''largo de narices'', el modismo hebreo para la paciencia o la lentitud para la ira. Esta frase es la columna vertebral de una de las fórmulas teológicas más fundamentales de la Escritura: ''Jehová, Jehová, compasivo y clemente, lento para la ira y grande en misericordia'' (Éx 34:6). Repetida en Joel, Jonás, Nahúm y múltiples Salmos, se convierte en el retrato definitivo del carácter de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0752', 'spa', 'Largo, prolongado (extendido en tiempo o espacio)', 'Adjetivo que significa largo o prolongado, aplicado tanto a dimensiones temporales como espaciales. Describe la guerra prolongada entre las casas de Saúl y David, que gradualmente debilitó a una y fortaleció a la otra. Jeremías lo usa para referirse al exilio que será largo, no breve. Job lo extiende metafóricamente a la sabiduría de Dios, que es más larga que la tierra y más ancha que el mar, es decir, infinita en alcance. El término capta la extensión más allá de la medida normal, ya sea en duración o en dimensión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0753', 'spa', 'Longitud; medida o dimensión espacial; duración temporal (''largura de días''); paciencia, tolerancia (''largura de ánimo'').', 'Longitud; medida o dimensión espacial; duración temporal (''largura de días''); paciencia, tolerancia (''largura de ánimo'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0757', 'spa', 'Arquita — adjetivo gentilicio que indica procedencia de la ciudad de Erec/Arka, aplicado principalmente a Husai, consejero de David.', 'El arquita (אַרְכִּי) es un adjetivo gentilicio que identifica a alguien originario de la ciudad de Erec o Arka, un asentamiento cercano a Betel cuyo territorio se menciona en Joshua 16:2. Su portador principal es Husai el arquita, el leal amigo y consejero de David que desempeñó un papel decisivo durante la rebelión de Absalón. Cuando David huyó de Jerusalén, Husai lo encontró en la cima del Monte de los Olivos y fue enviado de regreso para contrarrestar el consejo de Ahitofel (2 Sam 15:32). Su estrategia de demora — instar a Absalón a reunir a todo Israel antes de atacar — resultó decisiva y salvó la vida de David (2 Sam 17:5-14). También aparece en el registro de la corte de David como consejero real (1 Chr 27:33).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0758', 'spa', 'Aram — nombre propio de un pueblo semítico, su territorio en la alta Mesopotamia y Siria, y nombre personal en genealogías.', 'Aram aparece 133 veces como nombre tanto personal como geográfico. En la Tabla de las Naciones es el quinto hijo de Sem (Gn 10:22), y también designa a un nieto de Nacor (Gn 22:21). Sin embargo, con mucha mayor frecuencia el vocablo identifica al pueblo arameo y sus territorios, que se extendían desde el recodo del Éufrates, pasando por Damasco, hasta el norte de Siria — vecino persistente, rival y a veces señor de Israel y Judá. Las expresiones compuestas Aram-Naharáyim (''Aram de los dos ríos'', Gn 24:10), Aram-Damasco y Aram-Sobá identifican reinos arameos específicos. Las guerras entre Israel y Aram dominan buena parte de Reyes y Crónicas (1 Re 20; 2 Re 5-8). La Septuaginta lo traduce habitualmente como Siria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0759', 'spa', 'Estructura fortificada: palacio o residencia real; ciudadela o bastión defensivo.', 'Estructura fortificada: palacio o residencia real; ciudadela o bastión defensivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0761', 'spa', 'Arameo — persona de Aram (Siria), usado como adjetivo gentilicio para el pueblo y la región al noreste de Israel.', 'Arameo — persona de Aram (Siria), usado como adjetivo gentilicio para el pueblo y la región al noreste de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0762', 'spa', 'En arameo; designación adverbial que especifica la lengua aramea como medio de habla o escritura.', 'Adverbio que significa ''en arameo'', usado para identificar la lengua de comunicación en contextos diplomáticos y reales. En 2 Reyes 18:26 e Isaías 36:11, los funcionarios judíos ruegan al enviado asirio que hable en arameo en lugar de hebreo para que el pueblo común en la muralla no comprenda. Esdras 4:7 señala dos veces que una carta fue escrita y traducida ''en arameo'', y Daniel 2:4 marca el célebre punto de transición donde los caldeos se dirigen al rey en arameo, tras lo cual el texto bíblico mismo cambia a esa lengua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0763', 'spa', 'Aram-Naharáyim, ''Aram de los dos ríos'', la región mesopotámica entre el Éufrates y sus afluentes.', 'Topónimo compuesto que significa ''Aram de los dos ríos'', designando la región de la alta Mesopotamia entre los ríos Éufrates y Habor (o Balij), aproximadamente equivalente al Padán-aram de las narrativas patriarcales. El siervo de Abraham viaja allí para buscar esposa para Isaac (Gn 24:10), y es la tierra natal de Cusán-Risataim, el primer opresor de Israel en Jueces 3:8. El título del Salmo 60:1 recuerda las campañas de David en esta región, mientras que Deuteronomio 23:4 y 1 Crónicas 19:6 la relacionan con Balaam y las guerras amonitas respectivamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0769', 'spa', 'Arnón; río (actual Wadi Mujib) que forma la frontera entre Moab y el territorio amorreo en Transjordania', 'Arnón; río (actual Wadi Mujib) que forma la frontera entre Moab y el territorio amorreo en Transjordania');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0771', 'spa', 'Ornán -- el jebuseo dueño de la era que David compró como sitio para el futuro templo', 'Ornán -- el jebuseo dueño de la era que David compró como sitio para el futuro templo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0772', 'spa', 'Tierra, suelo (arameo); el suelo físico o el mundo habitado, cognado del hebreo ''erets''', 'Tierra, suelo (arameo); el suelo físico o el mundo habitado, cognado del hebreo ''erets''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0774', 'spa', 'Arpad, una ciudad-estado aramea en el norte de Siria conquistada por Asiria, siempre emparejada con Hamat en oráculos proféticos.', 'Una importante ciudad-estado aramea ubicada a unos veinticinco kilómetros al norte de Alepo en el norte de Siria, identificada con la actual Tell Erfad. En cada aparición bíblica, Arpad se menciona junto a Hamat como ejemplo admonitorio de la conquista asiria, ya sea en la provocación del Rabsaces (2 Kgs 18:34; Isa 36:19), en el oráculo de Isaías contra la arrogancia asiria (Isa 10:9) o en la profecía de Jeremías contra Damasco (Jer 49:23). Este emparejamiento constante subraya cuán universalmente reconocida era esta ciudad como símbolo de la resistencia caída ante el poder imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0775', 'spa', 'Arfaxad, tercer hijo de Sem y antepasado en la línea genealógica de Noé a Abraham.', 'Nombre propio que designa al tercer hijo de Sem, incluido en la Tabla de las Naciones (Gn 10:22) y en la genealogía que conecta a Noé con Abraham (Gn 11:10-13). Arfaxad es un eslabón clave en el linaje escogido a través del cual fluyen las promesas del pacto. El nombre probablemente tiene un origen geográfico, quizá vinculado a la región caldea o a Arrapaquitis, cerca de Nínive. Las versiones en distintos idiomas son notablemente uniformes: en español ''Arfaxad'' o ''Arpajsad'', en francés ''Arpachshad'' o ''Arpacschad'', reflejando los desafíos fonéticos de este antiguo nombre semítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0776', 'spa', 'tierra, país, suelo; el mundo, el territorio de una nación o la superficie física del terreno', 'Sustantivo hebreo fundamental que articula la geografía, la cosmología y la teología bíblicas. En el relato de la creación, אֶרֶץ forma par con שָׁמַיִם (cielo) para designar el cosmos, pero en los libros históricos se estrecha a territorios concretos —''la tierra de Egipto'', ''la tierra de Canaán''— haciendo inseparables la geografía y la teología del pacto. Cuando se refiere a naciones, las traducciones emplean vocabulario territorial; cuando describe el cosmos creado, recurren a términos de alcance mundial. La acepción de suelo aparece con verbos de caer o postrarse, donde se enfoca la superficie física.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0779', 'spa', 'Maldecir o pronunciar una maldición; como participio pasivo, estar en estado de maldición o ser maldito.', 'Maldecir o pronunciar una maldición; como participio pasivo, estar en estado de maldición o ser maldito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0780', 'spa', 'Ararat; región montañosa en la Armenia oriental donde el arca de Noé reposó tras el Diluvio.', 'Nombre geográfico que designa el territorio montañoso de Urartu en la Armenia oriental, entre el río Araxes y los lagos Van y Urmía. Es célebre como el lugar donde reposó el arca de Noé (Gn 8:4, «los montes de Ararat»). En 2 Reyes 19:37 e Isaías 37:38, los hijos de Senaquerib huyen a la «tierra de Ararat» tras asesinar a su padre. Jeremías 51:27 convoca a los «reinos de Ararat» junto con Mini y Askenaz contra Babilonia, reflejando su condición de entidad política reconocida en el antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0781', 'spa', 'Desposar, comprometerse en matrimonio; en el Piel el varón contrae activamente el desposorio, en el Pual la mujer es descrita como desposada. Verbo re', 'Desposar, comprometerse en matrimonio; en el Piel el varón contrae activamente el desposorio, en el Pual la mujer es descrita como desposada. Verbo reservado exclusivamente para el acto formal de desposorio, el compromiso legalmente vinculante que precedía al matrimonio en el antiguo Israel. En el Piel, el varón es la parte activa que asegura a la novia, a menudo con un precio establecido (2 Sam 3:14: «a quien desposé por cien prepucios»). Oseas transforma este lenguaje transaccional en una teología del pacto sobrecogedora: Dios desposa a Israel «en justicia, en juicio, en misericordia y en compasión» (Os 2:19-20), donde el precio nupcial es el carácter divino mismo. El Pual pasivo describe el estado resultante de la mujer como desposada, condición que conlleva un peso legal serio en la legislación deuteronómica (Dt 22:23-28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0783a', 'spa', 'Artajerjes — nombre real persa; el rey o reyes aqueménidas bajo cuyo reinado sirvieron Esdras y Nehemías. El nombre אַרְתַּחְשַׁשְׂתְּא (Artachshasta)', 'Artajerjes — nombre real persa; el rey o reyes aqueménidas bajo cuyo reinado sirvieron Esdras y Nehemías. El nombre אַרְתַּחְשַׁשְׂתְּא (Artachshasta), traducido «Artajerjes» siguiendo la forma griega, identifica a uno o posiblemente dos monarcas persas que autorizaron proyectos de restauración judía. Artajerjes I Longímano (465-424 a.C.) es el más comúnmente identificado: comisionó la misión de Esdras para restaurar la observancia de la Torá (Esd 7:1, 7, 11-12) y concedió a Nehemías permiso para reconstruir las murallas de Jerusalén (Neh 2:1; 5:14; 13:6). El nombre también aparece en la correspondencia de Esdras 4:7-23, donde los adversarios apelan al rey para detener la reconstrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0783b', 'spa', 'Artajerjes; forma aramea del nombre del rey persa que aparece en las secciones de correspondencia de Esdras.', 'La grafía aramea del nombre real persa Artajerjes (אַרְתַּחְשַׁשְׂתְּא), presente en las secciones documentales arameas de Esdras. Esta forma, con su característica desinencia enfática aramea, identifica al emperador persa que autorizó la misión de Esdras y las obras de reconstrucción en Jerusalén. El nombre probablemente corresponde a Artajerjes I Longímano (465-424 a.C.), cuyos decretos fueron decisivos para la restauración de la vida judía en el período postexílico. La Septuaginta lo traduce como Artaxerxes, confirmando la identificación en todas las tradiciones de traducción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0784', 'spa', 'Fuego; llamas y combustión física; también fuego como presencia divina, instrumento de juicio y relámpago celeste.', 'אֵשׁ es la palabra hebrea primaria para el fuego en todas sus manifestaciones, desde la fogata para asar el cordero pascual (Éx 12:8) hasta la columna de fuego que guio a Israel por el desierto. Pocos vocablos portan tanto peso teológico sin dejar de ser tan concretos. El fuego es el elemento que Dios elige repetidamente para revelarse: la zarza ardiente que no se consume (Éx 3:2), la gloria en el Sinaí que semeja ''fuego devorador'' (Éx 24:17) y el fuego que desciende sobre el sacrificio de Elías (1 Re 18:38). La evidencia multilingüe confirma la amplitud del término: el árabe نار y el coreano 불 funcionan como la palabra no marcada para el fuego físico, pero las lenguas añaden modificadores cuando el fuego adquiere dimensión divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0787', 'spa', 'Cimiento, fundamento arquitectónico (préstamo arameo del asirio uššû); base estructural de un edificio', 'Término arameo tomado del asirio que aparece exclusivamente en el relato de Esdras sobre la reconstrucción del templo de Jerusalén. Designa la estructura de cimentación de un edificio, en particular del templo. Las tres ocurrencias se concentran en Esdras 4-6, donde funcionarios persas y líderes judíos debaten la legitimidad de la obra de reconstrucción. La evidencia multilingüe confirma de manera consistente el sentido arquitectónico del vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0788', 'spa', 'Asbel, segundo hijo de Benjamín; nombre propio posiblemente compuesto con Baal', 'Nombre propio del segundo hijo de Benjamín, que aparece en las listas genealógicas de Génesis, Números y Crónicas. Su etimología es incierta, posiblemente un compuesto relacionado con Baal (Esbaal) o con el juramento. La Septuaginta presenta variantes (Asbel, Asuber, Saba), lo que sugiere incertidumbre escribal sobre la pronunciación del nombre. Sus descendientes formaron uno de los clanes benjaminitas contados en el censo del desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0794', 'spa', 'Laderas o cañadas montañosas, usadas en descripciones geográficas del terreno de Canaán, especialmente las laderas del Pisga.', 'Sustantivo femenino que designa el terreno inclinado en la ladera de una montaña, particularmente las zonas por donde el agua desciende formando cauces. Se encuentra solo en plural y aparece en las fórmulas geográficas estándar de Deuteronomio y Josué que catalogan las regiones de la Tierra Prometida: región montañosa, Néguev, llanura y laderas. La expresión ''las laderas del Pisga'' (Deut 3:17; 4:49; Josh 12:3; 13:20) se convirtió en una fórmula fija. El término captura el sentido de terreno descendente que canaliza el agua hacia tierras más bajas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0795', 'spa', 'Asdod -- una importante ciudad filistea en la costa mediterránea, una de las cinco ciudades de la pentápolis', 'Asdod -- una importante ciudad filistea en la costa mediterránea, una de las cinco ciudades de la pentápolis');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0796', 'spa', 'Asdodita, adjetivo gentilicio para los habitantes de la ciudad filistea de Asdod, usado como sustantivo o modificador.', 'Adjetivo gentilicio derivado de Asdod, una de las cinco ciudades principales de los filisteos en la costa mediterránea. Aparece tanto como singular colectivo con artículo — ''el asdodita'', refiriéndose a la población asdodita en su conjunto (Josh 13:3) — como en plural para designar a los habitantes que sufrieron cuando el arca estuvo entre ellos (1 Sam 5:3, 6). En tiempos de Nehemías, el término adquiere un significado cultural: las ''mujeres asdoditas'' con quienes se casaron los judíos (Neh 13:23) y la gente de Asdod que se opuso a la reconstrucción del muro (Neh 4:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0798', 'spa', 'Pisga, cumbre montañosa en Moab; cima desde la cual Moisés contempló la Tierra Prometida', 'Esta montaña en Moab, probablemente una cumbre de la cordillera de Abarim, le concedió a Moisés su única visión de Canaán antes de morir. La «cumbre del Pisga» fue el último lugar desde donde Balac intentó que Balaam maldijera a Israel. Sus «laderas» o «manantiales» sirvieron como límites territoriales. El nombre posiblemente deriva de una raíz que significa «hendidura», lo que sugiere un rasgo geológico distintivo. La tradición judía suele identificarlo con el monte Nebo, aunque la relación exacta entre ambos nombres sigue siendo incierta. Su importancia teológica supera con creces su precisión geográfica: un lugar de revelación divina y anhelo humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0801', 'spa', 'Ofrenda encendida; un sacrificio presentado a Yahvé mediante la combustión sobre el altar.', 'Ofrenda encendida; un sacrificio presentado a Yahvé mediante la combustión sobre el altar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0802', 'spa', 'mujer, esposa, hembra; persona femenina ya sea soltera, casada o como pareja de un animal', 'Junto a אִישׁ (''hombre''), אִשָּׁה es una de las palabras más fundamentales de la Escritura, con 781 apariciones que abarcan las principales identidades sociales de la mujer en el antiguo Oriente Próximo: mujer por derecho propio, esposa y —en dos usos formulares— hembra de un animal. Su primera aparición es programática: Adán exclama ''será llamada אִשָּׁה porque de אִישׁ fue tomada'' (Gn 2:23), etimología popular que vincula varón y mujer a nivel lingüístico. El plural נָשִׁים (de raíz diferente) sirve tanto para ''mujeres'' como para ''esposas'', y solo el contexto determina cuál sentido se aplica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0804', 'spa', 'Asur/Asiria; el ancestro epónimo, o la nación, imperio, tierra y pueblo de Asiria.', 'En la Tabla de las Naciones (Gn 10:22), Asur aparece como hijo de Sem y ancestro de la civilización asiria, uno de los pueblos más antiguos mencionados en las Escrituras. Sin embargo, con mucha mayor frecuencia la misma forma designa la entidad geopolítica Asiria: su territorio, sus ejércitos invasores y su poder imperial que se cernió sobre Israel y Judá durante siglos. Los profetas lo emplean como amenaza y como símbolo: la ''vara de mi enojo'' de Isaías (Is 10:5) y el aliado inútil de Oseas (Os 12:2). Las tradiciones de traducción reflejan esta doble identidad: el español ''Asiria'' sirve tanto para la persona como para la nación, mientras que el alemán distingue ''Assur'' (persona) de ''Assyrien'' (territorio).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0809', 'spa', 'Torta de pasas; masa prensada de uvas secas usada como alimento festivo y en ofrendas cultuales.', 'Sustantivo que designa una torta prensada elaborada con pasas, manjar apreciado en el antiguo Israel que se distribuía en celebraciones y se empleaba en fiestas religiosas. David repartió tortas de pasas a todo Israel durante la procesión del arca (2 S 6:19; 1 Cr 16:3). En Cantares 2:5 se utilizan como remedio para el mal de amor: «sustentadme con tortas de pasas». Oseas 3:1 condena expresamente el apego de Israel a las tortas de pasas ofrecidas a dioses ajenos, vinculando este manjar con la idolatría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0811', 'spa', 'Racimo, especialmente de uvas; usado literalmente para la producción del viñedo y figuradamente para belleza o juicio.', 'Designa un racimo de uvas, célebre sobre todo por el enorme racimo que los espías israelitas trajeron del valle de Escol (Nm 13:23-24), el cual dio nombre al valle. La palabra aparece tanto en contextos agrícolas literales — el copero del faraón ve racimos madurando en su sueño (Gn 40:10) — como en un rico uso figurado: al amado se le compara con racimos de flores de alheña (Cnt 1:14; 7:8-9), mientras que Deuteronomio 32:32 emplea ''racimos de hiel'' para condenar a los enemigos de Israel. El término español ''racimo'' y el francés ''grappe'' confirman el significado central en diversas lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0812', 'spa', 'Escol, nombre propio que designa tanto a un aliado amorreo de Abraham como a un valle rico en uvas cerca de Hebrón.', 'Nombre que significa ''racimo'' (de uvas), aplicado a dos referentes estrechamente relacionados. Primero, Escol es un jefe amorreo y hermano de Mamre que se alió con Abraham en el rescate de Lot (Gen 14:13, 24). Segundo, el Valle de Escol cerca de Hebrón es el célebre lugar donde los espías israelitas cortaron un sarmiento con un enorme racimo de uvas (Num 13:23-24), que se convirtió en símbolo perdurable de la abundancia de la tierra. La etimología del nombre se hace explícita en Num 13:24, conectando el lugar con el fruto que los espías encontraron allí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0813', 'spa', 'Asquenaz, descendiente de Jafet y pueblo del norte; posiblemente los ascanios de Bitinia', 'Funciona tanto como nombre propio como designación étnica. Como persona, Asquenaz fue descendiente de Jafet a través de Gomer. Como pueblo, aparece en el oráculo de Jeremías contra Babilonia, convocado junto con Ararat y Mini para atacarla. Los estudiosos lo identifican con un pueblo del norte, posiblemente los ascanios de Bitinia o un grupo armenio. La tradición judía posterior aplicó el nombre a las tierras germánicas, pero las referencias bíblicas apuntan a Anatolia o la región del Cáucaso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0815', 'spa', 'Tamarisco, árbol probablemente sagrado que marcaba santuarios; plantado por Abraham, cobijó a Saúl', 'Especie arbórea (tamarisco) mencionada en contextos que sugieren significación sagrada. Abraham plantó uno en Beerseba, posiblemente para señalar un santuario. Saúl celebraba consejo bajo un tamarisco en Guibeá, y sus restos fueron sepultados bajo otro. El tamarisco es un arbusto-árbol perennifolio de hojas escamosas que prospera en regiones áridas y aparentemente se valoraba como referencia para sitios sagrados. La identificación botánica se mantiene consistente en las diversas tradiciones de traducción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0816', 'spa', 'Ofender, ser culpable, incurrir en culpa — cometer una transgresión o hacerse responsable ante Dios, a veces implicando desolación como consecuencia.', 'Ofender, ser culpable, incurrir en culpa — cometer una transgresión o hacerse responsable ante Dios, a veces implicando desolación como consecuencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0817', 'spa', 'Culpa, ofensa o transgresión; ofrenda por la culpa (sacrificio); compensación o restitución por una falta.', 'Culpa, ofensa o transgresión; ofrenda por la culpa (sacrificio); compensación o restitución por una falta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0818', 'spa', 'Culpable, que carga con culpa que requiere expiación o restitución; responsable de una ofensa', 'Adjetivo que describe el estado de culpabilidad y la consiguiente obligación de hacer restitución u ofrecer sacrificio. Los hermanos de José confiesan ser culpables respecto a él (Génesis 42:21). La parábola de David plantea una cuestión sobre la culpa (2 Samuel 14:13). Quienes se casaron con mujeres extranjeras en tiempos de Esdras son declarados culpables y deben ofrecer un carnero como ofrenda por la culpa. El término abarca tanto la responsabilidad moral como la obligación ritual: una culpa que debe resolverse por los cauces establecidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0819', 'spa', 'Culpa o culpabilidad ante Dios; también ofensas o transgresiones concretas consideradas como actos culpables', 'Culpa o culpabilidad ante Dios; también ofensas o transgresiones concretas consideradas como actos culpables');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0821', 'spa', 'Vigilia nocturna; división de las horas de la noche usada para guardia militar y cómputo poético del tiempo.', 'Sustantivo femenino que designa una ''vigilia'', es decir, una de las divisiones en que los antiguos israelitas repartían la noche. Se reconocían tres vigilias: la primera, la de en medio y la de la mañana. El término aparece tanto en contextos militares como poéticos: la vigilia de la mañana junto al Mar Rojo cuando Dios sembró confusión en el campamento egipcio (Éx 14:24), el ataque sorpresa de Gedeón al inicio de la vigilia intermedia (Jue 7:19) y el asalto de Saúl contra los amonitas al amanecer (1 S 11:11). En los Salmos se convierte en metáfora de la brevedad del tiempo: mil años ante los ojos de Dios son como una vigilia nocturna (Sal 90:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0826', 'spa', 'Conjurador o encantador, término arameo para los adivinos de la corte babilónica en el libro de Daniel.', 'Sustantivo arameo que designa una clase de magos de la corte babilónica dedicados a la adivinación, el encantamiento o la astrología. Aparece exclusivamente en las secciones arameas de Daniel, en listas de sabios profesionales convocados por el rey para interpretar sueños y señales (Dan 2:10, 27; 4:7; 5:7, 11, 15). Probablemente es un préstamo lingüístico del babilónico. En español se traduce tanto como «astrólogos» como «encantadores», lo cual refleja la incertidumbre sobre la especialidad divinatoria exacta que el término abarca. El inglés usa consistentemente «enchanters», mientras que la falta de traducción del hebreo en ediciones francesas y alemanas sugiere la oscuridad técnica del vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0827', 'spa', 'Aljaba, estuche o recipiente para portar flechas, usado literal y figuradamente en contextos de guerra y propósito divino.', 'Sustantivo femenino que designa el recipiente en el que se transportan las flechas, derivado del asirio ishpatu. Aunque aparece en contextos militares directos —la aljaba que resuena contra el caballo de guerra (Job 39:23), Elam descubriendo su aljaba para la batalla (Isa 22:6), la aljaba de Babilonia como sepulcro abierto (Jer 5:16)— sus usos más memorables son figurados. En el Salmo 127:5, el hombre que llena su aljaba de hijos es llamado bienaventurado, comparando a los hijos con flechas. En Isaías 49:2, el Siervo del Señor es una flecha pulida escondida en la aljaba de Dios, sugiriendo tanto preparación como ocultamiento hasta el tiempo señalado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0830', 'spa', 'Muladar, montón de cenizas, basurero; lugar de desechos que simboliza pobreza extrema y degradación.', 'Sustantivo masculino que designa un montón de cenizas, basura o estiércol, equivalente en el antiguo Cercano Oriente a un vertedero. En las Escrituras funciona con gran fuerza como símbolo de destitución absoluta. El cántico de Ana celebra que Dios levanta al pobre del muladar para sentarlo entre príncipes (1 S 2:8), tema que resuena en el Salmo 113:7. Lamentaciones 4:5 invierte la imagen con efecto devastador: quienes antes se deleitaban con manjares ahora abrazan muladares. En Nehemías, la ''Puerta del Muladar'' servía como referencia topográfica práctica en las murallas de Jerusalén (Neh 2:13; 3:13-14; 12:31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0831', 'spa', 'Ascalón -- una de las cinco ciudades principales filisteas, en la costa mediterránea de Canaán', 'Ascalón -- una de las cinco ciudades principales filisteas, en la costa mediterránea de Canaán');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0833', 'spa', 'Ir derecho, avanzar; declarar bienaventurado/dichoso; guiar o dirigir; corregir. Pual: ser llamado bienaventurado o ser guiado', 'Ir derecho, avanzar; declarar bienaventurado/dichoso; guiar o dirigir; corregir. Pual: ser llamado bienaventurado o ser guiado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0834a', 'spa', 'partícula relativa: que, quien, el cual; también relativo sustantivado (lo que) y ocasionalmente conjunción causal o temporal', 'אֲשֶׁר es el pilar de la sintaxis hebrea, la partícula que enlaza oraciones y permite al idioma señalar hacia atrás, adelante y en múltiples direcciones. En la inmensa mayoría de sus usos funciona como pronombre relativo universal —''que'', ''quien'', ''el cual''—, cubriendo con una sola partícula lo que el español necesita varias palabras para expresar. Sus raíces etimológicas probablemente se remontan a un sustantivo que significaba ''lugar'' (cf. asirio ashar, arameo atar), lo que explica su evolución: de ''el lugar donde'' a ''el que'' y de ahí a conector clausal general. En los márgenes, puede adquirir fuerza causal (''porque'', como en Sal 95:11) o temporal (''cuando'', como en Sal 139:15), aunque estos usos son excepcionales frente a su función relativa dominante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0834b', 'spa', 'Conjunción compuesta ba''asher: locativo ''donde, dondequiera''; causal ''porque, por cuanto''; relativo ''en el/la cual, en lo que''', 'Conjunción compuesta ba''asher: locativo ''donde, dondequiera''; causal ''porque, por cuanto''; relativo ''en el/la cual, en lo que''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0834c', 'spa', 'Preposición relativa compuesta: de quien/del cual/de donde; que (comparativo); porque/puesto que (causal)', 'Preposición relativa compuesta: de quien/del cual/de donde; que (comparativo); porque/puesto que (causal)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0834d', 'spa', 'Como, así como (comparativo); cuando (temporal); porque, puesto que (causal); conforme a lo que; después de.', 'La conjunción compuesta כַּאֲשֶׁר (literalmente ''como aquello que'') es uno de los subordinantes más versátiles del hebreo, formado por la preposición כְּ (''como'') y la partícula relativa אֲשֶׁר. Su función primaria es comparativa — ''como Dios mandó a Noé'' (Gn 7:9) — pero se desliza con facilidad hacia el terreno temporal (''cuando terminó de hablar'', Gn 18:33) y ocasionalmente marca causa (''porque no temieron al SEÑOR'', 2 Re 17:26). Esta polisemia refleja el comportamiento bien conocido de ''as'' en inglés y comme en francés. El español distingue las acepciones con mayor nitidez: como para la comparación, cuando para el tiempo y porque para la causa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0835', 'spa', '!Bienaventurado! !Dichoso! — fórmula de bienaventuranza que declara a alguien afortunado, siempre en el constructo plural אַשְׁרֵי.', '!Bienaventurado! !Dichoso! — fórmula de bienaventuranza que declara a alguien afortunado, siempre en el constructo plural אַשְׁרֵי.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0836', 'spa', 'Aser — octavo hijo de Jacob por medio de Zilpa; la tribu israelita asentada en la fértil región costera del noroeste', 'Aser — octavo hijo de Jacob por medio de Zilpa; la tribu israelita asentada en la fértil región costera del noroeste');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0838a', 'spa', 'Paso, pisada, caminar; término poético para el andar o curso de vida, siempre con sufijos posesivos.', 'Sustantivo femenino que significa ''paso'' o ''pisada'', usado exclusivamente en poesía y literatura sapiencial para describir el camino o la manera de vivir. Siempre aparece con sufijos pronominales — ''mis pasos'', ''sus pasos'', ''nuestros pasos'' — nunca en forma absoluta, lo que le confiere una cualidad profundamente personal. Job declara que su pie se ha aferrado a los pasos de Dios (Job 23:11), el salmista ora para que sus pasos no resbalen (Sal 17:5), y los pasos del justo no vacilan porque la ley de Dios está en su corazón (Sal 37:31). La palabra conecta el caminar físico con la dirección moral, haciendo de cada pisada una declaración de fidelidad o fracaso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0842', 'spa', 'Asera — diosa cananea, o el poste de culto de madera/árbol sagrado erigido en su honor en los lugares altos', 'Asera — diosa cananea, o el poste de culto de madera/árbol sagrado erigido en su honor en los lugares altos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0844', 'spa', 'Asriel, nombre de clan manasita; posiblemente significa ''voto de Dios''', 'Nombre de un clan de la tribu de Manasés que aparece en listas censales y de distribución territorial. El nombre podría significar ''voto de Dios'', combinando elementos divinos y votivos. El clan de Asriel recibió una porción en el reparto de tierras al oeste del Jordán. Como muchos nombres tribales, Asriel puede referirse tanto a una persona (el ancestro del clan) como al grupo familiar que desciende de él. El nombre se conserva con mínima variación en los textos hebreos, españoles y franceses.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0847', 'spa', 'Estaol; ciudad en la Sefela asignada a Dan, estrechamente asociada con Zora y la historia de Sansón.', 'Nombre propio que identifica la ciudad de Estaol, ubicada en la Sefela (tierras bajas de las colinas) de Judá, asignada a la tribu de Dan. Casi siempre se menciona junto a Zora, su ciudad hermana, formando un par reconocible en el texto bíblico. Estaol ocupa un lugar destacado en la narrativa de Sansón: el Espíritu del Señor comenzó a manifestarse en él entre Zora y Estaol (Jue 13:25), y fue sepultado en la tumba de su padre entre ambas ciudades (Jue 16:31). También sirvió como punto de partida para la migración danita hacia el norte (Jue 18:2, 8, 11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0851', 'spa', 'Estemoa, ciudad levítica en la serranía de Judá al sur de Hebrón; también nombre personal en Crónicas.', 'Nombre propio con dos referentes. Principalmente designa una ciudad levítica en la serranía meridional de Judá, identificada con la moderna es-Samu'' al sur de Hebrón. Aparece en las listas de ciudades de Josué (15:50; 21:14) y como uno de los destinos a los que David envió botín tras derrotar a los amalecitas (1 Sam 30:28). En Crónicas también figura como nombre personal —un hombre de Judá (1 Cr 4:17, 19). La forma alternativa Estemoh (Jos 15:50) y la forma estándar Estemoa representan la misma localidad. El español «Estemoa» y el inglés «Eshtemoa» transliteran el hebreo con variaciones menores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0852', 'spa', 'Señales, prodigios u presagios (arameo); indicadores milagrosos de la acción divina', 'Palabra aramea que designa señales o prodigios, presente exclusivamente en las secciones arameas del libro de Daniel. Nabucodonosor y Darío hablan de las señales y maravillas que el Dios Altísimo realiza. El término se solapa semánticamente con el hebreo אוֹת, pero aparece en contextos de proclamación real, donde reyes paganos reconocen las intervenciones milagrosas de Dios. Su significado fundamental es el de indicadores visibles o demostraciones sobrenaturales del poder divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0853', 'spa', 'Marcador de objeto directo definido; también preposición homográfica que significa ''con, junto a''', 'Una de las palabras más frecuentes de la Biblia hebrea, apareciendo casi 11.000 veces. En la gran mayoría de casos funciona como señal intraducible del objeto directo definido — la partícula que indica ''este sustantivo recibe la acción.'' Aparece en el primer versículo de las Escrituras: Dios creó ''et los cielos y ''et la tierra (Gén 1:1). Una preposición homográfica pero etimológicamente distinta ''et significa ''con, junto a'' y aparece unas 62 veces, como en Salmo 2:11 ''servid a Jehová con temor.'' La mayoría de traducciones simplemente absorben el marcador de objeto en el orden de palabras, mientras que el español ocasionalmente lo representa con la ''a'' personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0854', 'spa', 'con, junto con (compañía); de con (fuente ablativa con מִן); también funciona como marca de objeto directo en ciertas tradiciones textuales', 'La preposición אֵת (con tsere largo, distinta de la homógrafa marca de objeto directo אֶת con seghol) es la palabra hebrea primaria para ''con'' en sentido de compañía: estar junto a alguien, caminar con Dios, habitar con la familia. Aparece en algunas de las declaraciones teológicas más íntimas de la Biblia: Dios ''estaba con José'' (Gn 39:2), ''Yo estoy contigo'' (Gn 26:24), y la promesa de Emanuel, ''Dios con nosotros''. Cuando se le antepone מִן, adquiere sentido ablativo de procedencia: ''de parte del SEÑOR'' (Gn 19:24), y alguien sale ''de con'' un rey. En ciertos libros tardíos, las formas sufijadas de esta preposición se solapan ortográficamente con la marca de objeto directo, creando un desafío de análisis persistente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0855', 'spa', 'Herramienta cortante de hierro —reja de arado o azadón— instrumento emblemático de la profecía de espadas convertidas en arados.', 'Implemento agrícola cortante hecho de hierro, traducido como «reja de arado» o «azadón». Sus apariciones más célebres están en Isaías 2:4 y Miqueas 4:3, donde las naciones convierten sus espadas en rejas de arado, una de las imágenes más perdurables de paz escatológica en las Escrituras. Joel 3:10 invierte dramáticamente la imagen: «forjad espadas de vuestros azadones». En 1 Samuel 13:20-21, el monopolio filisteo sobre la herrería obligaba a los israelitas a acudir a los filisteos para afilar sus azadones, ilustrando las dinámicas de poder en la Edad del Hierro temprana. Una ocurrencia (2 Re 6:5) probablemente sea un marcador de objeto directo mal atribuido y no este sustantivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0857', 'spa', 'Venir, llegar (sinónimo poético de בּוֹא); como participio: las cosas venideras, eventos futuros; Hifil: traer', 'Venir, llegar (sinónimo poético de בּוֹא); como participio: las cosas venideras, eventos futuros; Hifil: traer');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0858', 'spa', 'Verbo arameo estándar para el movimiento hacia un destino, equivalente cotidiano del hebreo bo. En Esdras y Daniel cubre todo el espectro de llegada y', 'Verbo arameo estándar para el movimiento hacia un destino, equivalente cotidiano del hebreo bo. En Esdras y Daniel cubre todo el espectro de llegada y entrega. Funcionarios ''vienen'' a investigar el templo reconstruido (Esd 5:3), dignatarios son convocados a ''venir'' a la dedicación de Nabucodonosor (Dan 3:2), y el enigmático ''uno como hijo de hombre'' viene con las nubes del cielo (Dan 7:13). La forma Hafel (causativa) cambia la acción: Belsasar ordena que ''traigan'' los vasos del templo a su banquete (Dan 5:2-3), y Daniel es ''traído'' ante el rey (Dan 5:13). El Hofal pasivo completa el panorama: una piedra es ''traída'' y colocada sobre el foso de los leones (Dan 6:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0859a', 'spa', 'tú — pronombre personal independiente de segunda persona masculino singular para vocativo y énfasis', 'Attah es el pronombre independiente de segunda persona masculino singular, empleado para énfasis, contraste o apelación directa a lo largo de la Biblia hebrea. Con 743 apariciones, puede funcionar solo como sujeto (''ciertamente morirás'', Gn 2:17) o reforzar un sufijo verbal con valor enfático (''pregunta tú'', 1 S 17:56). Marca frecuentemente un cambio de interlocutor — de la narración a la confrontación, como en las palabras de Dios a la serpiente (''maldito eres tú'', Gn 3:14) o en las escenas de confesión de David. Las traducciones multilingües — español ''tú'', francés ''tu'', alemán ''du'' — reflejan uniformemente esta única función pronominal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0859b', 'spa', 'Tú (pronombre de segunda persona singular, forma femenina arcaica/dialectal conservada en lecturas ketiv)', 'Tú (pronombre de segunda persona singular, forma femenina arcaica/dialectal conservada en lecturas ketiv)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0859c', 'spa', 'Tú (fem. sg.) — pronombre personal independiente de segunda persona femenino singular, usado para dirigirse a una mujer individualmente.', 'Tú (fem. sg.) — pronombre personal independiente de segunda persona femenino singular, usado para dirigirse a una mujer individualmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0859d', 'spa', 'Vosotros (pronombre independiente de segunda persona masculino plural).', 'El pronombre independiente de segunda persona masculino plural en hebreo, empleado para dirigirse directamente a grupos. Con 283 apariciones, se encuentra a lo largo de toda la Biblia hebrea cuando un hablante se dirige enfáticamente a un auditorio masculino o mixto. José confronta a sus hermanos con él (Gn 42:9, 16), y reaparece con frecuencia en el discurso legal y profético. A veces aparece después del verbo para dar énfasis (Jue 15:12) e incluso se construye con referentes femeninos en Ezequiel 13:20, reflejando la flexibilidad del hebreo bíblico tardío. Las traducciones lo vierten uniformemente con la forma plural de segunda persona correspondiente a cada lengua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0859e', 'spa', 'Pronombre de segunda persona femenino plural ''vosotras'', dirigido a un grupo de mujeres o entidades femeninas.', 'Pronombre independiente de segunda persona femenino plural ''vosotras'', usado al dirigirse a múltiples sujetos femeninos. En Génesis 31:6 Jacob se dirige a sus dos esposas Lea y Raquel, recordándoles que ellas saben cómo él ha servido a su padre. Ezequiel emplea esta forma extensamente: en 13:11 y 13:20 Dios se dirige a las falsas profetisas, y en 34:17 y 34:31 el rebaño de Dios es interpelado con gramática femenina, ya que la palabra hebrea para rebaño (צֹאן) es gramaticalmente femenina. El español ''vosotras'' conserva la distinción de género que el inglés moderno ha perdido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0860', 'spa', 'Asna, burra; animal doméstico usado para montar, transportar carga y como medida de riqueza', 'Asna, burra; animal doméstico usado para montar, transportar carga y como medida de riqueza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0861', 'spa', 'Horno (arameo) — el horno ardiente o de fundición, usado para el horno de fuego en Daniel 3. El sustantivo arameo אַתּוּן (attun) designa un horno o k', 'Horno (arameo) — el horno ardiente o de fundición, usado para el horno de fuego en Daniel 3. El sustantivo arameo אַתּוּן (attun) designa un horno o kiln grande calentado a temperaturas extremas. Las diez ocurrencias aparecen en Daniel 3, donde Nabucodonosor ordena arrojar a Sadrac, Mesac y Abednego a un horno de fuego ardiente por negarse a adorar su imagen de oro. El horno se calienta «siete veces más de lo acostumbrado» (Dn 3:19), tan caliente que mata a los soldados que arrojan a los tres (Dn 3:22). Sin embargo, Nabucodonosor ve cuatro figuras caminando ilesas en las llamas (Dn 3:25). La palabra tiene cognados con el hebreo אָתוֹן (horno/fogón) y el acadio utūnu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0862b', 'spa', 'Galería o terraza; elemento arquitectónico del templo visionario de Ezequiel, un corredor cubierto o repisa escalonada.', 'Sustantivo masculino que designa galerías o terrazas en el templo visionario de Ezequiel 40-42. Estos elementos arquitectónicos parecen ser corredores cubiertos, repisas escalonadas o balcones dispuestos en niveles a lo largo de la estructura exterior del templo. Las cinco apariciones se concentran en Ezequiel 41:15-16 y 42:3-5, donde describen las cámaras de tres pisos que flanquean el templo propiamente dicho. El término es notoriamente difícil de traducir, pero el contexto sugiere plataformas elevadas y retranqueadas que otorgaban a los pisos superiores progresivamente menos superficie.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0863', 'spa', 'Itai, nombre propio de dos hombres de David: un comandante gitita y un guerrero benjaminita.', 'El nombre Itai (posiblemente ''compañero'', derivado de אֵת, ''con'') lo llevan dos personajes del círculo de David. El más destacado es Itai el gitita, un soldado extranjero de Gat que mostró una lealtad extraordinaria durante la revuelta de Absalón, insistiendo en seguir a David al exilio (2 S 15:19-22) y comandando luego un tercio del ejército en la batalla decisiva (2 S 18:2, 5, 12). El segundo Itai es un benjaminita entre los treinta valientes de David (2 S 23:29; cf. 1 Cr 11:31). Las traducciones conservan uniformemente el nombre: ''Itai'' en español e ''Ittai'' en inglés y francés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0864', 'spa', 'Etam; lugar en el borde del desierto donde Israel acampó tras salir de Egipto.', 'Parada en la ruta del éxodo de Israel, situada en la frontera entre la tierra cultivada de Egipto y el desierto abierto. Etam aparece en el itinerario de Números 33 y en la narración de Éxodo 13:20, marcando la transición del territorio habitado al desierto. El «desierto de Etam» (Nm 33:8) se convirtió en un hito determinante de las primeras etapas de la travesía por el desierto. El nombre podría derivar de un vocablo egipcio que significa «fortaleza» o «recinto», acorde con su ubicación fronteriza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0865', 'spa', 'Ayer; anteriormente, en tiempos pasados — adverbio temporal para el pasado reciente o un estado habitual previo.', 'Adverbio temporal que significa ''ayer'' en sentido literal, pero que con frecuencia se extiende a ''anteriormente'' o ''en tiempos pasados''. Aparece de forma memorable en el modismo recurrente temol shilshom (''ayer y anteayer''), expresión hebrea equivalente a ''como antes'' o ''previamente'' (p. ej., 1 S 4:7; 2 S 5:2). Las traducciones multilingües confirman este doble alcance: el alemán gestern y el español ayer se ciñen al sentido literal, mientras que el francés autrefois (''antiguamente'') y el inglés ''in time past'' reflejan el uso retrospectivo más amplio. En contextos proféticos como Isaías 30:33 y Miqueas 2:8, transmite la fuerza de un recuerdo reciente y vívido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0868', 'spa', 'Paga de ramera, salario de prostituta — pago dado por servicios sexuales, usado literalmente y como metáfora de las ganancias idolátricas de Israel. E', 'Paga de ramera, salario de prostituta — pago dado por servicios sexuales, usado literalmente y como metáfora de las ganancias idolátricas de Israel. El sustantivo אֶתְנַן (etnan) denota específicamente la paga entregada a una prostituta, con fuerza tanto literal como metafórica poderosa. Deuteronomio 23:18 prohíbe llevar «la paga de una ramera o el precio de un perro» a la casa del SEÑOR como ofrenda votiva. La alegoría extendida de Ezequiel sobre Jerusalén como esposa infiel invierte la convención: ella es peor que una ramera común porque paga a sus amantes en vez de recibir pago (Ez 16:31-34, 41). Isaías profetiza que las ganancias comerciales de Tiro serán «paga de ramera» consagrada al SEÑOR (Is 23:17-18). Miqueas declara que los ídolos de Samaria fueron reunidos con salario de ramera y volverán a ser salario de ramera (Mi 1:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0870', 'spa', 'Sustantivo arameo ''lugar, sitio'' y uso preposicional ''después de, tras''; en Daniel y Esdras para el sitio del templo y la sucesión temporal.', 'Sustantivo arameo que significa ''lugar'' o ''sitio'', empleado en los libros de Daniel y Esdras para designar una ubicación física, especialmente el emplazamiento del templo de Jerusalén (Esd 5:15; 6:3, 5, 7). En un desarrollo secundario compartido con el siríaco batar y el uso targúmico, la palabra adquiere valor preposicional con el sentido de ''después de'' o ''tras'', como en Daniel 7:6-7, donde reinos sucesivos surgen ''después de esto''. El cognado árabe ithr (''huella, rastro'') ilustra cómo una raíz espacial se desplaza hacia la secuencia temporal: se sigue ''en la huella de'' lo anterior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0874', 'spa', 'Aclarar, explicar o escribir de forma legible (Piel); hacer algo comprensible y distinto', 'Verbo en la forma intensiva (Piel) que significa hacer algo claro o comprensible. Moisés explica la ley con claridad (Deuteronomio 1:5). Las inscripciones deben escribirse de manera legible sobre piedras, tan claras que se puedan leer al pasar corriendo o de forma rápida (Habacuc 2:2). La ley sobre piedras encaladas debe escribirse ''muy claramente'' (Deuteronomio 27:8). El énfasis recae en la claridad y accesibilidad de la comunicación escrita, especialmente en textos legales y proféticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0875', 'spa', 'Pozo excavado para obtener agua; en sentido figurado, fosa de destrucción o peligro moral', 'Pozo excavado para obtener agua; en sentido figurado, fosa de destrucción o peligro moral');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0877', 'spa', 'Cisterna, pozo o foso; depósito de agua excavado, a menudo contrastado con manantiales de agua viva.', 'Designa una cavidad excavada para almacenar agua, ya sea cisterna, pozo o foso. La palabra aparece memorablemente en Jeremías 2:13, donde Dios se contrasta a sí mismo como fuente de agua viva frente a las «cisternas rotas» que Israel se ha labrado. En 2 Samuel 23:15–16 se refiere al pozo de Belén del que los valientes de David sacaron agua. La forma es una variante del más común בְּאֵר/בּוֹר, y su sentido se mantiene constante como receptáculo para contener agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0881', 'spa', 'Beerot, ciudad gabaonita asignada a Benjamín, cuyo nombre significa ''pozos'', vinculada a la liga hevea.', 'Beerot es un topónimo que significa ''pozos'' (בְּאֵרוֹת), referido a una de las cuatro ciudades gabaonitas que lograron un pacto con Israel mediante engaño (Jos 9:17). Situada en el territorio de Benjamín (Jos 18:25), la ciudad es recordada especialmente por ser el lugar de origen de Recab y Baaná, los asesinos de Is-boset, identificados como beerotitas en 2 Samuel 4:2. Sus habitantes reaparecen en las listas del censo postexílico de Esdras 2:25 y Nehemías 7:29, lo que atestigua la continuidad de esta comunidad tras el destierro babilónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0883', 'spa', 'Beer-lajai-roi, nombre de pozo que significa ''pozo del Viviente que me ve''; lugar del encuentro de Agar', 'Nombre de lugar que conmemora el encuentro de Agar con el Ángel del Señor. Su significado es ''pozo del Viviente que me ve'', explicado en Génesis 16:14 por la certeza de Agar de que Dios la vio en su aflicción. El pozo se encontraba entre Cades y Béred, en el Néguev. Isaac vivía cerca de Beer-lajai-roi cuando llegó Rebeca (Génesis 24:62) y se estableció allí tras la muerte de Abraham (Génesis 25:11). Este sitio marcó un lugar de encuentro divino y de importancia continua para la familia patriarcal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0884', 'spa', 'Beerseba — ciudad del Neguev que marca el límite sur tradicional de Israel, asociada con Abraham e Isaac', 'Beerseba — ciudad del Neguev que marca el límite sur tradicional de Israel, asociada con Abraham e Isaac');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0886', 'spa', 'Beerotita, gentilicio que identifica a los habitantes de Beerot, ciudad benjaminita.', 'Adjetivo gentilicio que significa ''el beerotita'' (בְּאֵרֹתִי), designando a alguien originario de la ciudad de Beerot en Benjamín. Las cinco apariciones se concentran en 2 Samuel, principalmente en el capítulo 4, que narra el asesinato de Is-boset a manos de Recab y Baaná. El texto identifica reiteradamente a estos hombres como beerotitas (2 Sam 4:2, 3, 5, 9), subrayando su procedencia, quizá para distinguirlos de la casa de Saúl o para señalar que la población hevea de Beerot había huido a Guitaim. Naharai, uno de los valientes de David, también recibe este gentilicio (2 Sam 23:37).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0887', 'spa', 'Este verbo hebreo capta tanto la realidad física del hedor como la realidad social de la desgracia. En su sentido literal, describe el olor pútrido de', 'Este verbo hebreo capta tanto la realidad física del hedor como la realidad social de la desgracia. En su sentido literal, describe el olor pútrido del maná podrido, los peces muertos en el Nilo azotado por la plaga o las heridas infectadas. Pero el hebreo usa la misma raíz para la desgracia social: hacerse ''heder'' ante los ojos de alguien significa destruir la propia reputación. Los israelitas le dijeron a Moisés que los había hecho ''odiosos'' ante Faraón, tal como David se hizo odioso ante los filisteos. El idioma trata la repugnancia social con la misma intensidad visceral que la descomposición física.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0889', 'spa', 'Hedor, olor fétido de descomposición; olor de cadáveres o materia putrefacta', 'Sustantivo que designa el hedor de la muerte y la descomposición. El término aparece en oráculos proféticos de juicio donde los cadáveres yacen insepultos y su hedor asciende (Isaías 34:3). La plaga de langostas de Joel deja un olor fétido al morir el enjambre (Joel 2:20). Amós habla de Dios enviando pestilencia de modo que ''el hedor de vuestros campamentos subió a vuestras narices'' (Amós 4:10). La imagen es visceral: retrata las consecuencias del juicio divino cuando los cuerpos se descomponen a la intemperie. El hedor se convierte en un marcador sensorial de la catástrofe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0893', 'spa', 'Bebai, nombre propio de un jefe de familia cuyos descendientes aparecen entre los exiliados que regresaron en Esdras y Nehemías.', 'Nombre propio que aparece en los registros postexílicos de Esdras y Nehemías. Bebai encabeza una familia cuyos descendientes regresaron de Babilonia en dos oleadas: 623 en un recuento (Esd 2:11) y 628 en la lista paralela (Neh 7:16). Miembros adicionales de su familia regresaron con Esdras (Esd 8:11), y algunos figuraron entre quienes habían tomado mujeres extranjeras (Esd 10:28). Un Bebai también aparece como signatario del pacto de Nehemías (Neh 10:16). La traducción alemana «in-in-mir» parece ser un error de traducción, mientras que el inglés y el español transliteran correctamente el nombre como Bebai/Bevai.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0894', 'spa', 'Babilonia, Babel; la antigua capital mesopotámica sobre el Éufrates, sede del Imperio neobabilónico.', 'Con 262 apariciones, Babel/Babilonia es tanto un topónimo como un símbolo entretejido en toda la narrativa bíblica. Aparece por primera vez en Génesis como el lugar de la torre y la confusión de lenguas (Gn 11:9, vinculado por juego de palabras con בָּלַל, ''confundir''). Resurge como la potencia mundial dominante que destruyó Jerusalén y deportó a Judá bajo Nabucodonosor (2 Re 24-25). Los profetas pronuncian oráculos contra ella (Is 13-14; Jer 50-51) y los salmistas lloran junto a sus ríos (Sal 137). Casi todas las lenguas conservan el nombre como transliteración directa: español Babilonia, francés Babylone, alemán Babel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0895', 'spa', 'Babilonia (Babel); la gran ciudad y el imperio mesopotámico, centro del exilio y símbolo de soberbia humana y juicio divino', 'Babilonia (Babel); la gran ciudad y el imperio mesopotámico, centro del exilio y símbolo de soberbia humana y juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0898', 'spa', 'Actuar traidoramente, obrar con deslealtad; como participio, persona traidora o traidor.', 'Actuar traidoramente, obrar con deslealtad; como participio, persona traidora o traidor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0899b', 'spa', 'Vestidura, prenda de vestir; cualquier cobertura corporal, desde los harapos de un leproso hasta las vestimentas sacerdotales.', 'בֶּגֶד es la palabra hebrea estándar para designar una vestidura o prenda de vestir, abarcando todo el espectro desde la ropa de uso diario hasta las vestiduras sagradas del sumo sacerdote (Éx 28:2-3). Aparece en relatos de engaño (Gn 27:15, donde Rebeca viste a Jacob con las ropas de Esaú), de duelo (rasgarse las vestiduras) y de consagración (Lv 8:30). El español lo traduce variadamente como ''vestidos'' o ''vestiduras'', el francés como ''vêtements'' y el alemán como ''Gewänder''. Cabe notar que la misma raíz ב-ג-ד da origen al verbo que significa ''obrar con traición'', sugiriendo quizá que la ropa puede ocultar tanto como cubrir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0902', 'spa', 'Bigvai, nombre propio de un líder entre los exiliados que regresaron en tiempos de Zorobabel y Nehemías.', 'Nombre propio llevado por al menos una figura prominente del período postexílico. Bigvai fue uno de los líderes que regresaron de Babilonia con Zorobabel (Ezra 2:2; Neh 7:7) y dio nombre a una familia numerosa: 2.056 descendientes en un censo (Ezra 2:14) y 2.067 en la lista paralela (Neh 7:19). Un segundo grupo de su familia regresó con Esdras (Ezra 8:14). Un Bigvai también aparece como signatario del pacto de Nehemías (Neh 10:17). El nombre posiblemente derive del sánscrito bhagavan (''afortunado'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0905', 'spa', 'Separación, solo, por sí mismo; aparte de, además de; también: varas, miembros del cuerpo, ramas, cerrojos.', 'El sustantivo בַּד abarca un notable abanico semántico enraizado en la idea de separación o partición. En su uso más frecuente, con la preposición לְ y sufijos pronominales, significa ''solo, por sí mismo'' — desde la declaración de Dios de que no es bueno que el hombre esté solo (Gn 2:18) hasta la fórmula exclusiva ''aparte de, además de''. Como sustantivo concreto, designa objetos separados o extendidos: las varas de transporte del mobiliario del tabernáculo, los miembros de un cuerpo, las ramas de una vid o los cerrojos de una puerta. El árabe بِدّ (porción) conserva el núcleo partitivo, mientras que las extensiones concretas muestran cómo una sola raíz de ''separación'' se ramifica hacia referentes físicos diversos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0906', 'spa', 'Tela de lino blanco; tejido fino usado para vestiduras sacerdotales y vestimentas sagradas en el culto del tabernáculo y el templo', 'Tela de lino blanco; tejido fino usado para vestiduras sacerdotales y vestimentas sagradas en el culto del tabernáculo y el templo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0907', 'spa', 'Habladuría vana, jactancia o mentiras; por extensión, mentirosos y falsos profetas. También: miembros del cuerpo.', 'Sustantivo que aparece solo en plural (בַּדִּים) y abarca dos significados bastante distintos. Principalmente designa el habla vacía, jactanciosa o engañosa: las infundadas fanfarronadas de Moab (Isa 16:6; Jer 48:30), la palabrería ociosa del adversario de Job (Job 11:3) y las mentiras de falsos profetas o adivinos (Isa 44:25; Jer 50:36). Este sentido tiene cognados fenicios y paralelos siríacos que significan ''habla vana'' o ''mentiroso''. Un sentido homónimo completamente diferente aparece en Job 41:12, donde se describen los poderosos miembros (בַּדָּיו) de Leviatán, uso confirmado por vocabulario corporal uniforme en las traducciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0909', 'spa', 'Solo, aislado, solitario; describe la separación de un grupo o comunidad.', 'Describe el estado de estar separado, aislado o solitario. La forma participial transmite una imagen vívida de soledad: un leproso que habita apartado fuera del campamento (Lv 13:46), un ave solitaria sobre un tejado (Sal 102:7), un rezagado separado de las filas (Is 14:31) o Efraín comparado con un asno montés que vaga solo (Os 8:9). La raíz verbal se conecta con el sentido árabe de retiro y acción independiente, reflejando de manera constante aislamiento y separación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0910', 'spa', 'Solo, solitario, aislado — describe un estado de separación, ya sea independencia digna o soledad desoladora. El adjetivo/adverbio בָּדָד (badad) desc', 'Solo, solitario, aislado — describe un estado de separación, ya sea independencia digna o soledad desoladora. El adjetivo/adverbio בָּדָד (badad) describe el estado de estar solo, aparte o aislado. Su rango semántico se extiende desde la separación noble hasta la soledad devastadora. El oráculo de Balaam celebra a Israel como «un pueblo que habita solo, que no se cuenta entre las naciones» (Nm 23:9) — la soledad como elección divina. La despedida de Moisés bendice a Israel: «así Israel habita seguro, solo» (Dt 33:28), y Deuteronomio 32:12 recuerda que «solo el SEÑOR lo guió». Sin embargo, Lamentaciones abre con el grito angustiado: «¡Cómo está sentada sola la ciudad populosa!» (Lm 1:1), donde la misma palabra expresa desolación total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0913', 'spa', 'Estaño, aleación o escoria; metal base separado del mineral precioso, también usado como peso de plomada.', 'En el vocabulario del antiguo metalurgista, bedil se refería ampliamente al residuo impuro que queda al fundir metal precioso. Números 31:22 lo enumera junto con oro, plata, bronce, hierro y plomo como botín de guerra que requiere purificación por fuego. En Ezequiel 22:18-20, Israel misma se convierte en estaño mezclado con escoria en el horno de Dios. Isaías 1:25 precisa el significado como la impureza que Dios promete purgar de Jerusalén, mientras Zacarías 4:10 usa ''la piedra de estaño'' como plomada en la mano de Zorobabel, símbolo de precisión en la reconstrucción.');